-- Înlocuiește textele celor 112 activități din banda 2–3, S1–S4.
-- Întâi copiază rândurile, exact cum sunt înainte de UPDATE, în
-- backup_20261116_gifted_s1s4, inclusiv nota. Apoi fiecare UPDATE cere
-- id-ul, banda 2–3 și textul vechi (titlul, pașii și nota) din acel backup.
-- Dacă un rând nu se potrivește, migrarea se oprește și tranzacția se anulează.
-- Nota celor 112 rânduri devine goală. Dacă textele noi sunt deja scrise și
-- nota e deja goală, rularea nu mai schimbă nimic.
-- Nu atinge copiii, bifele sau săptămânile din afara S1–S4.
-- Nu se aplică pe Familie din acest PR.

do $gifted$
declare
  plan record;
  snap_titlu text;
  snap_pasi text[];
  snap_nota text;
  cur_titlu text;
  cur_pasi text[];
  cur_materiale text[];
  cur_durata integer;
  cur_gata text;
  cur_plus text;
  cur_provocare text;
  cur_siguranta text;
  cur_nota text;
  updated_count int := 0;
  skipped_count int := 0;
  touched int;
begin
  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'activities'
      and column_name = 'pas_in_plus'
  ) then
    raise exception 'Gifted S1–S4: lipsește coloana pas_in_plus. Aplică întâi migrarea de schemă.';
  end if;

  create temporary table gifted_plan (
    id text primary key,
    old_titlu text not null,
    old_pasi text[] not null,
    old_nota text,
    titlu text not null,
    materiale text[] not null,
    durata_min integer not null,
    pasi text[] not null,
    gata_cand text not null,
    pas_in_plus text not null,
    provocare text not null,
    siguranta text
  ) on commit drop;

  insert into gifted_plan (
    id, old_titlu, old_pasi, old_nota, titlu, materiale, durata_min, pasi, gata_cand,
    pas_in_plus, provocare, siguranta
  ) values
    ($q$s1-b23-z1-mental$q$, $q$Trei locuri din casă$q$, array[$q$Arătați trei locuri: „Ușă. Fereastră. Scaun.”$q$, $q$Întrebați blând: „Unde e ușa?” și așteptați arătarea.$q$, $q$Dacă vrea: spuneți o dată: „Casă.” și arătați camera.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Turul casei: ce e și la ce folosește$q$, array[$q$casa întreagă; un coșuleț; 4–5 obiecte de-ale lui$q$]::text[], 10, array[$q$Faceți turul a trei camere. În fiecare, el numește 3 lucruri, iar voi extindeți: „Da, fereastra, pe unde intră lumina.”$q$, $q$Întrebați „La ce folosim ușa? Dar scaunul?” și așteptați 5–10 secunde răspunsul lui.$q$, $q$Puneți în coș 4 obiecte (lingură, carte, pernă, periuță) și întrebați: „În ce cameră stă fiecare?”$q$, $q$Duce el fiecare obiect în camera lui și spune propoziția: „Lingura stă în bucătărie.”$q$]::text[], $q$A spus în ce cameră stau cel puțin 3 obiecte și la ce folosește unul dintre ele, într-o propoziție.$q$, $q$Lucrul fără loc fix: „Unde stă umbrela? De ce acolo, lângă ușă?”$q$, $q$Ghicitoare inversă: voi descrieți („E moale, stă în dormitor, punem capul pe ea”), el ghicește. Apoi îl lăsați pe el să vă dea o ghicitoare.$q$, null),
    ($q$s1-b23-z1-fizic$q$, $q$Pași din casă în curte$q$, array[$q$Deschideți ușa împreună și faceți câțiva pași în curte.$q$, $q$Arătați: „Aici e curtea. Am ieșit din casă.”$q$, $q$Dacă vrea: alegeți împreună unde stați 10 secunde — lângă ușă sau mai departe.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Traseul casă–curte în 4 opriri$q$, array[$q$ușa spre curte; pantofi; 4 repere (treapta, nucul, banca, poarta închisă)$q$]::text[], 10, array[$q$Spuneți traseul o dată, înainte de a ieși: „Treapta, nucul, banca, apoi înapoi la ușă.”$q$, $q$Pornește el în față; la fiecare oprire întrebați: „Unde mergem acum?”$q$, $q$La fiecare reper face un gest ales de el (bate palma de copac, se așază pe bancă).$q$, $q$La ușă, spune traseul înapoi, din memorie, cu sprijinul vostru.$q$]::text[], $q$A condus cel puțin 3 opriri în ordinea spusă la început.$q$, $q$Un mod de mers pe fiecare porțiune: în vârfuri până la nuc, cu pași de urs până la bancă.$q$, $q$Planifică el traseul pentru voi (3 opriri), iar voi îl urmați exact; dacă greșiți intenționat, vă corectează.$q$, $q$Poarta rămâne închisă; un adult stă la o lungime de braț lângă trepte și fântână.$q$),
    ($q$s1-b23-z1-social$q$, $q$Salut spațiului: bună, casă$q$, array[$q$La intrare, bateți ușor în ușă și spuneți: „Bună, casă!”$q$, $q$Zâmbiți și așteptați dacă vrea să imite gestul.$q$, $q$Dacă vrea: adăugați: „Ușă.” când atingeți clanța.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Spunem bună și explicăm cui$q$, array[$q$niciunul$q$]::text[], 5, array[$q$La intrare, spuneți „Bună, casă!” și întrebați-l: „Cui mai spunem bună?”$q$, $q$Mergeți la 3 locuri sau oameni aleși de el (bunica, pisica, nucul) și salută el fiecare.$q$, $q$Întrebați: „Ce-i spunem nucului, în afară de bună?” Ascultați propoziția lui.$q$, $q$Închideți: „Pe cine ai salutat azi?” El enumeră.$q$]::text[], $q$A salutat cel puțin 3 locuri sau oameni și și-a amintit cel puțin 2 dintre ei la final.$q$, $q$Salut cu o urare: „Bună, nucule, să crești mare!”$q$, $q$Salutul diferit după cine e: „Cum o saluți pe bunica? Dar un bebeluș? Dar un câine?” (voce, gest, cuvinte potrivite).$q$, null),
    ($q$s1-b23-z1-resurse$q$, $q$Jucăria la loc după joacă$q$, array[$q$Luați o jucărie folosită și mergeți la locul ei.$q$, $q$Puneți-o împreună: „La loc. Gata joaca.”$q$, $q$Dacă vrea: alegeți între cutie și raft unde o puneți.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Fiecare lucru are casa lui$q$, array[$q$5–6 jucării folosite; cutii și raft cu loc fix$q$]::text[], 6, array[$q$Întrebați: „Unde e casa mașinii? Dar a cărții?”$q$, $q$Duce el fiecare jucărie la locul ei, fără să-i arătați voi, doar cu întrebări.$q$, $q$Pentru una, întrebați „De ce stă aici și nu pe jos?”$q$, $q$La final, verifică el raftul: „Mai lipsește ceva de la locul lui?”$q$]::text[], $q$A dus singur cel puțin 4 jucării la locul lor și a verificat raftul.$q$, $q$Instrucțiune în 3 pași: „Pune cartea pe raft, mingea în coș și vino să-mi spui gata.”$q$, $q$Voi puneți intenționat un lucru la locul greșit (o lingură în cutia cu cuburi): „E ceva care nu stă unde trebuie?”$q$, null),
    ($q$s1-b23-z2-mental$q$, $q$Unde e curtea?$q$, array[$q$Stați la fereastră/ușă: „Unde e curtea?”$q$, $q$Arătați și spuneți: „Curte.”$q$, $q$Dacă vrea: comparați: „În casă e cald. Afară e curtea.”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$La fereastră: ce e în curte și ce lipsește$q$, array[$q$fereastra spre curte$q$]::text[], 8, array[$q$Priviți împreună și întrebați: „Ce vezi în curte?” Extindeți fiecare răspuns cu o însușire: „Da, găleata roșie, lângă gard.”$q$, $q$Întrebați unde e fiecare lucru: „Lângă ce e găleata? Ce e lângă nuc?”$q$, $q$Închideți ochii amândoi: „Spune-mi 3 lucruri din curte, fără să te uiți.”$q$, $q$Deschideți și verificați: „Ai spus găleata, nucul, poarta. Le-ai nimerit pe toate?”$q$]::text[], $q$A numit din memorie cel puțin 3 lucruri din curte și a folosit „lângă” sau „după” pentru unul.$q$, $q$Ce s-a schimbat față de ieri (frunze căzute, găleata mutată).$q$, $q$Un părinte mută ceva în curte cât el nu se uită (scaunul, găleata): „Ce s-a schimbat?”$q$, null),
    ($q$s1-b23-z2-fizic$q$, $q$Explorează două zone$q$, array[$q$Mergeți la o zonă (de exemplu iarbă sau hol), stați 20 de secunde. Pe balcon, țineți-l de mână.$q$, $q$Mergeți la a doua zonă și numiți-o: „Aici e…”.$q$, $q$Dacă vrea: întrebați: „Unde mergem din nou?” și urmați alegerea lui.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Zonele curții: iarbă, pietriș, umbră$q$, array[$q$curtea; 3 obiecte-semn (găleată, cerc de sfoară, baston)$q$]::text[], 10, array[$q$Puneți câte un semn în trei zone: pe iarbă, pe pietriș, la umbră.$q$, $q$Spuneți: „Când zic iarbă, alergi la găleată; pietriș, la cerc; umbră, la baston.”$q$, $q$Jucați 5–6 runde; schimbați ordinea.$q$, $q$La final, întrebați: „Care zonă e cea mai caldă? De ce?”$q$]::text[], $q$A ajuns la zona potrivită în cel puțin 4 runde din 6.$q$, $q$Două zone la rând: „Iarbă, apoi umbră!”$q$, $q$Regula pe dos o rundă: „Acum mergi oriunde, numai nu unde zic eu.”$q$, $q$Fără alergat pe pietriș cu papuci; verificați curtea de obiecte ascuțite înainte.$q$),
    ($q$s1-b23-z2-social$q$, $q$Arătăm curtea adultului$q$, array[$q$Invitați-l să arate cu mâna un loc din curte.$q$, $q$Spuneți: „Uite ce arată el!” și denumiți locul.$q$, $q$Dacă vrea: lăsați-l să aleagă ce arată — copac, poartă sau iarbă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ghidul curții pentru un oaspete$q$, array[$q$un ursuleț sau un membru al familiei, ca oaspete$q$]::text[], 8, array[$q$Spuneți: „Ursulețul n-a mai fost la noi. Îi arăți tu curtea?”$q$, $q$Îl duce el pe oaspete în 3 locuri și spune ce e acolo: „Aici e nucul. Aici ne jucăm.”$q$, $q$Oaspetele pune o întrebare la fiecare loc: „De ce e iarba udă?”$q$, $q$La final, oaspetele mulțumește, iar el spune ce i-a plăcut cel mai mult să arate.$q$]::text[], $q$A arătat cel puțin 3 locuri și a spus despre fiecare o propoziție.$q$, $q$O regulă a curții pentru oaspete: „Aici nu călcăm, sunt flori.”$q$, $q$Oaspetele face o greșeală (vrea să deschidă poarta): copilul explică de ce nu e voie și ce facem în schimb.$q$, null),
    ($q$s1-b23-z2-resurse$q$, $q$Pantofii la loc după ieșire$q$, array[$q$După ce ați fost afară, luați pantofii împreună.$q$, $q$Puneți-i pe loc: „Pantofii la loc.”$q$, $q$Dacă vrea: numărați: „Un pantof. Doi pantofi. Gata.”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Pantofii la ușă, perechi și ordine$q$, array[$q$3–4 perechi de pantofi ai familiei; preșul de la ușă$q$]::text[], 5, array[$q$După ieșire, întrebați: „Ai cui sunt pantofii aceștia?”$q$, $q$Face el perechile: „Care e perechea acestui pantof?”$q$, $q$Îi așază pe preș de la cei mai mari la cei mai mici.$q$, $q$Întrebați: „De ce lăsăm pantofii la ușă?”$q$]::text[], $q$A făcut cel puțin 2 perechi corecte și a spus ai cui sunt.$q$, $q$Al doilea criteriu: pantofi de curte și pantofi de casă, în două rânduri.$q$, $q$Un pantof lipsă (ascuns de voi): „Care pantof n-are pereche? Unde l-am putea căuta?”$q$, null),
    ($q$s1-b23-z3-mental$q$, $q$Casă sau curte?$q$, array[$q$Arătați obiectul din casă: „Din casă.”$q$, $q$Arătați cel din curte: „Din curte.” Întrebați: „Care e din curte?”$q$, $q$Dacă vrea: lăsați-l să sorteze încă un obiect în cele două grupe.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Casă sau curte? Și din ce e făcut?$q$, array[$q$8 obiecte, toate mai mari decât pumnul lui: 4 din casă (cană de plastic, lingură de lemn, șosetă, carte), 4 din curte (con de brad, piatră mare, frunză mare, băț scurt); două coșuri$q$]::text[], 10, array[$q$Sortează el în două coșuri: casă și curte. Întrebați la fiecare: „De ce aici?”$q$, $q$Amestecați totul și sortați din nou, după o regulă nouă: „tare” și „moale”.$q$, $q$Întrebați: „Lingura de lemn și bățul sunt în coșuri diferite. Ce au la fel?”$q$, $q$Lăsați-l să inventeze el o a treia regulă.$q$]::text[], $q$A sortat singur după două reguli diferite, una după alta.$q$, $q$Două criterii deodată: o grilă din două sfori pe jos (casă / curte × tare / moale), în care pune el fiecare obiect.$q$, $q$Obiectul care nu încape în nicio categorie (o frunză uscată adusă în casă): „E din casă sau din curte acum?” Acceptați orice răspuns argumentat.$q$, $q$Obiecte mai mari decât 3,17 cm pe toate laturile; spălați mâinile după obiectele din curte.$q$),
    ($q$s1-b23-z3-fizic$q$, $q$Pași până la ușă și înapoi$q$, array[$q$Mergeți împreună până la ușă: „Ușa.”$q$, $q$Întoarceți-vă câțiva pași în casă: „Înapoi acasă.”$q$, $q$Dacă vrea: faceți traseul încă o dată, el alege ritmul.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Până la ușă și înapoi, de trei feluri$q$, array[$q$holul spre ușa de la intrare$q$]::text[], 8, array[$q$Întrebați: „În câte feluri putem merge până la ușă?” Ascultați propunerile.$q$, $q$Faceți drumul în trei feluri alese de el (de-a bușilea, în vârfuri, cu spatele, cu sprijin).$q$, $q$După fiecare, întrebați: „Care a fost cel mai greu? De ce?”$q$, $q$Al patrulea drum îl inventează el.$q$]::text[], $q$A făcut drumul în cel puțin 3 feluri și a spus care a fost cel mai greu.$q$, $q$Drumul cu o oprire la jumătate: „Când bat din palme, statuie!”$q$, $q$Drum cu o regulă de ținut minte: „Până la ușă mergi ca ursul, înapoi ca pisica.” Spuneți o singură dată.$q$, $q$Mersul cu spatele doar cu adult lângă el și pe hol liber.$q$),
    ($q$s1-b23-z3-social$q$, $q$Bună pe prag$q$, array[$q$Pe prag, spuneți unul altuia: „Bună!”$q$, $q$Așteptați răspunsul fără grabă.$q$, $q$Dacă vrea: adăugați un salut scurt spre curte: „Bună, curte!”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Pe prag: povestim ziua de ieri$q$, array[$q$pragul ușii; două scăunele$q$]::text[], 6, array[$q$Stați pe prag și spuneți: „Ieri am fost în curte. Ce am făcut acolo?”$q$, $q$Ascultați și întrebați „Și apoi?” până spune 2–3 lucruri.$q$, $q$Voi spuneți un lucru greșit, cu zâmbet: „Și apoi am văzut un elefant!” Așteptați să vă corecteze.$q$, $q$Încheiați: „Ce facem azi în curte?”$q$]::text[], $q$A povestit cel puțin 2 lucruri de ieri, în ordine.$q$, $q$„Cum te-ai simțit când…?” (vesel, supărat, obosit).$q$, $q$Planul de azi în 3 pași, spus de el: „Întâi…, apoi…, la final…”, apoi verificați seara dacă l-ați respectat.$q$, null),
    ($q$s1-b23-z3-resurse$q$, $q$Trei lucruri strânse$q$, array[$q$Alegeți trei lucruri de pe jos: „Una. Două. Trei.”$q$, $q$Puneți-le în cutie: „Ajunge. La loc.”$q$, $q$Dacă vrea: alegeți împreună un al patrulea lucru sau opriți-vă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Strângem după o regulă aleasă de el$q$, array[$q$8–10 lucruri împrăștiate pe covor; 2 cutii$q$]::text[], 6, array[$q$Întrebați: „Cum strângem: întâi ce?” Lăsați-l să aleagă regula (întâi cuburile, întâi ce e roșu).$q$, $q$Strânge el după regula lui, iar voi după aceeași regulă.$q$, $q$La jumătate, întrebați: „Câte au mai rămas: multe sau puține?”$q$, $q$Închide el cutiile și le duce la loc.$q$]::text[], $q$A ales o regulă de strâns și a respectat-o până la capăt.$q$, $q$Numărați împreună ultimele lucruri rămase (numărul doar în context).$q$, $q$Cursă cu clepsidra sau cu un cântec: „Reușim până se termină cântecul?” Apoi întrebați: „Ce ne-a ajutat să terminăm repede?”$q$, null),
    ($q$s1-b23-z4-mental$q$, $q$Ușa se deschide, ușa se închide$q$, array[$q$Deschideți încet: „Deschis.”$q$, $q$Închideți blând: „Închis.” Repetați o dată.$q$, $q$Dacă vrea: el alege: „Deschidem sau închidem?”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Deschis, închis, încuiat: ce se întâmplă dacă…$q$, array[$q$ușa unei camere; o ușă de dulap; o cutie cu capac; sertarul de jos$q$]::text[], 8, array[$q$Arătați trei uși: a camerei, a dulapului și capacul cutiei. „Ce au la fel?”$q$, $q$Întrebați: „Ce se întâmplă dacă lăsăm ușa de la curte deschisă?” Ascultați ideile lui (intră frigul, iese pisica).$q$, $q$Verificați una dintre idei: deschideți ușa un minut și simțiți aerul.$q$, $q$Încheiați cu propoziția lui: „Închidem ușa ca să…”$q$]::text[], $q$A spus o urmare a ușii lăsate deschise și a verificat-o.$q$, $q$Jumătate deschis: „E deschisă sau închisă acum?” Discutați.$q$, $q$„Ce ușă din casă nu se deschide niciodată fără un adult? De ce?” (ușa de la intrare, dulapul cu detergenți).$q$, $q$Atenție la degete în balamale; ușa o mișcă adultul.$q$),
    ($q$s1-b23-z4-fizic$q$, $q$Cărăm ceva ușor afară$q$, array[$q$Dați-i ceva ușor de cărat câțiva pași spre ușă.$q$, $q$Spuneți: „Tu porți. Mergem în curte.”$q$, $q$Dacă vrea: lăsați-l să aleagă ce cără — jucăria sau găleata.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Transport de marfă în curte$q$, array[$q$o găleată, un coș, 4–5 lucruri de cărat (pernă, minge mare, sticlă de plastic plină cu apă, 2 cuburi de lemn)$q$]::text[], 10, array[$q$Spuneți: „Avem de mutat lucrurile în curte, lângă bancă.”$q$, $q$Întrebați înainte: „Care e cel mai greu? Pe care îl cari în brațe și pe care în găleată?”$q$, $q$Le cară el; voi ajutați doar dacă cere.$q$, $q$Întrebați la final: „Ai avut dreptate? Care a fost cel mai greu?”$q$]::text[], $q$A prezis care obiect e cel mai greu și a verificat cărându-le.$q$, $q$Două lucruri deodată, unul în fiecare mână: „Cum faci să nu cadă?”$q$, $q$Lucru prea mare pentru el (un coș plin): „Cum îl ducem fără să-l ridici?” (îl tragem, îl împărțim, chemăm ajutor).$q$, $q$Greutăți mici, potrivite lui; drumul fără trepte.$q$),
    ($q$s1-b23-z4-social$q$, $q$Rândul la deschis ușa$q$, array[$q$Voi deschideți puțin: „Acum eu.”$q$, $q$Apoi: „Acum tu” — țineți mâna lui pe clanță dacă vrea.$q$, $q$Dacă vrea: încă un schimb de rând, apoi gata.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Paznicul ușii$q$, array[$q$o ușă de cameră$q$]::text[], 6, array[$q$El e paznicul. Oricine vrea să intre bate la ușă și spune parola, aleasă de el.$q$, $q$Voi bateți și spuneți parola; el deschide.$q$, $q$Schimbați: voi sunteți paznicul, el bate și spune parola.$q$, $q$O rundă cu parolă greșită: paznicul nu deschide până nu e spusă parola corectă.$q$]::text[], $q$A ales o parolă, a ținut minte regula și a deschis doar la parola corectă.$q$, $q$Două parole: una pentru intrare și una pentru ieșire.$q$, $q$Parola se schimbă la fiecare rundă: „Acum parola e un animal.” Ține minte noua regulă.$q$, $q$Ușa se deschide încet; nimeni nu ține degetele în balamale.$q$),
    ($q$s1-b23-z4-resurse$q$, $q$Haina pe cârlig după curte$q$, array[$q$După ieșire, luați haina împreună.$q$, $q$Puneți-o pe cârlig: „Haina la loc.”$q$, $q$Dacă vrea: întrebați: „Pe cârlig sau pe scaun?”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cuierul familiei$q$, array[$q$cuierul; hainele și căciulile familiei$q$]::text[], 5, array[$q$După curte, întrebați: „A cui e haina asta? Unde stă?”$q$, $q$Agață el hainele lui și duce hainele celorlalți la cuier.$q$, $q$Întrebați: „Cine mai are haina pe jos?”$q$, $q$Verifică el cuierul: „Are fiecare haina la loc?”$q$]::text[], $q$A pus cel puțin 2 haine la cuier și a spus ale cui sunt.$q$, $q$Ordinea la cuier: „Haina mamei în stânga, a ta în mijloc.” (stânga și dreapta doar arătate).$q$, $q$„Mâine plouă. Ce mai punem lângă cuier, ca să găsim repede?” (cizmele, umbrela).$q$, null),
    ($q$s1-b23-z5-mental$q$, $q$Hartă scurtă: trei cuvinte$q$, array[$q$Spuneți: „Casă. Ușă. Curte.” arătând fiecare.$q$, $q$Cereți: „Arată casa” — așteptați gestul.$q$, $q$Dacă vrea: includeți: „Casă.” lângă camera principală.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Harta casei pe o foaie mare$q$, array[$q$o foaie mare sau carton; creioane colorate groase; 3 jucării mici (mai mari decât pumnul lui)$q$]::text[], 12, array[$q$Desenați voi, în fața lui, trei dreptunghiuri: bucătăria, camera lui, ușa spre curte. Spuneți ce desenați.$q$, $q$El pune câte o jucărie pe hartă: „Ursul doarme în camera ta.”$q$, $q$Apoi duce jucăria în locul real de pe hartă.$q$, $q$Întrebați: „Unde e ursul pe hartă? Dar în casă?”$q$]::text[], $q$A legat cel puțin 2 locuri de pe hartă de locurile reale.$q$, $q$Comoara: ascundeți o jucărie, faceți un X pe hartă, el o caută.$q$, $q$El face X-ul pe hartă și ascunde comoara, iar voi căutați după harta lui.$q$, null),
    ($q$s1-b23-z5-fizic$q$, $q$Traseu: cameră, hol, ușă$q$, array[$q$Parcurgeți împreună: cameră → hol → ușă.$q$, $q$La fiecare oprire numiți locul.$q$, $q$Dacă vrea: el alege ordinea: „Întâi holul sau ușa?”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Traseul cu obstacole din casă$q$, array[$q$perne, un scaun, o pătură; holul$q$]::text[], 10, array[$q$Construiți împreună un traseu cu 4 obstacole: peste pernă, pe sub scaun, prin „tunelul” din pătură, până la ușă.$q$, $q$El spune traseul înainte să înceapă: „Întâi perna, apoi…”$q$, $q$Face traseul; voi spuneți ce face: „Acum ești sub scaun.”$q$, $q$Întrebați: „Ce schimbăm ca să fie mai greu?”$q$]::text[], $q$A parcurs traseul în ordinea spusă și a propus o schimbare.$q$, $q$Traseul cu ceva în mână (o minge pe care nu trebuie s-o scape).$q$, $q$Traseul invers, de la ușă spre cameră, fără să-l mai spuneți voi.$q$, $q$Scaunul stabil, perne pe covor; fără cățărat pe mobilă.$q$),
    ($q$s1-b23-z5-social$q$, $q$Invită adultul în curte$q$, array[$q$Modelați: „Hai în curte!” și întindeți mâna.$q$, $q$Mergeți împreună doar dacă vrea; altfel stați pe prag.$q$, $q$Dacă vrea: el „conduce” — voi urmați pașii lui.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Invitația, de la cap la coadă$q$, array[$q$niciunul$q$]::text[], 6, array[$q$El invită pe cineva din familie în curte, cu o propoziție întreagă: „Tata, vii cu mine în curte?”$q$, $q$Dacă persoana spune „Acum nu pot”, întrebați: „Ce facem? Când îl mai întrebăm?”$q$, $q$La ieșire, conduce el și spune unde merg.$q$, $q$La întoarcere, mulțumește: „Mulțumesc că ai venit.”$q$]::text[], $q$A făcut o invitație într-o propoziție și a reacționat la un răspuns.$q$, $q$Invitația cu motiv: „Vino să vezi melcul.”$q$, $q$Doi invitați care vor lucruri diferite: „Mama vrea la leagăn, tata la nuc. Ce facem?” Caută el o soluție (pe rând, întâi unul).$q$, null),
    ($q$s1-b23-z5-resurse$q$, $q$Cheile sau coșul la loc$q$, array[$q$Luați un obiect de la intrare (chei, eșarfă, coș).$q$, $q$Puneți-l pe locul lui: „Aici stă. La loc.”$q$, $q$Dacă vrea: verificați dacă mai e ceva de pus — alegeți 1 din 2.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Locul cheilor: ce stă la intrare și de ce$q$, array[$q$obiectele de la intrare (chei, coș, umbrelă, lesă)$q$]::text[], 5, array[$q$Întrebați: „Ce stă la intrare și de ce?”$q$, $q$Pune el fiecare obiect la locul lui și spune pentru ce e: „Cheile, ca să încuiem.”$q$, $q$Voi ascundeți cheile (vizibil, pe raftul greșit): „Ne trebuie cheile. Unde sunt?”$q$, $q$Le pune el la loc și întrebați: „De ce e bine să stea mereu în același loc?”$q$]::text[], $q$A pus cel puțin 3 obiecte la loc și a spus pentru ce e unul.$q$, $q$„Ce luăm când ieșim la plimbare? Dar când plouă?” (lista de ieșire, spusă de el).$q$, $q$„Ce s-ar întâmpla dacă cheile n-ar avea un loc al lor?” Povestiți împreună o mică întâmplare.$q$, null),
    ($q$s1-b23-z6-mental$q$, $q$Ce e al casei, ce e al curții$q$, array[$q$Arătați cana: „Din casă.” Frunza: „Din curte.”$q$, $q$Întrebați: „Unde stă cana?”$q$, $q$Dacă vrea: inventați un joc scurt de rol: „Eu sunt în casă, tu ești în curte.”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Detectivul de obiecte: al casei sau al curții?$q$, array[$q$un săculeț opac; 6 obiecte mari (cană de plastic, con de brad, lingură de lemn, piatră mare, șosetă, frunză mare)$q$]::text[], 10, array[$q$El bagă mâna în săculeț fără să se uite: „Ce simți? E tare sau moale? Neted sau zgrunțuros?”$q$, $q$Ghicește obiectul, apoi îl scoate și verifică.$q$, $q$Pune obiectul în grămada casei sau a curții și spune de ce.$q$, $q$La final: „Care a fost cel mai greu de ghicit?”$q$]::text[], $q$A descris prin atingere și a ghicit cel puțin 3 obiecte.$q$, $q$Voi descrieți un obiect din săculeț, el îl găsește doar prin atingere.$q$, $q$Obiect-surpriză nemaiîntâlnit (un fluier mare din lemn): „Ce crezi că e? La ce folosește?”$q$, $q$Fără obiecte ascuțite sau mici în săculeț.$q$),
    ($q$s1-b23-z6-fizic$q$, $q$Iarbă, piatră, potecă$q$, array[$q$Pășiți pe două texturi diferite (cu pantofi dacă e nevoie).$q$, $q$Numeți: „Moale. Dur.” sau „Iarbă. Piatră.”$q$, $q$Dacă vrea: alegeți o a treia textură de explorat 10 secunde.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Colecția de texturi a curții$q$, array[$q$curtea; un carton cu 4 pătrate desenate$q$]::text[], 10, array[$q$Mergeți desculți (unde e sigur) sau cu mâna pe 4 texturi: iarbă, pietriș, scoarță, pământ.$q$, $q$La fiecare, el caută cuvântul: „moale”, „înțeapă”, „rece”, „aspru”.$q$, $q$Aduceți câte o bucată mare din fiecare (o frunză, o piatră mare, o bucată de scoarță) și le pune el pe carton.$q$, $q$Ordonați-le: „de la cea mai moale la cea mai aspră”.$q$]::text[], $q$A descris cel puțin 3 texturi cu cuvinte diferite și le-a ordonat.$q$, $q$Pe nevăzute: cu ochii închiși, recunoaște textura după atingere.$q$, $q$„Unde ar dormi cel mai bine un arici? De ce?” Alege textura și explică.$q$, $q$Verificați zona de cioburi și înțepături; spălați mâinile după.$q$),
    ($q$s1-b23-z6-social$q$, $q$Joacă paralel în curte$q$, array[$q$Stați lângă el cu propria jucărie; comentați ce face el.$q$, $q$Nu preluați jocul; oferiți un cuvânt: „Tu construiești.”$q$, $q$Dacă vrea: schimbați pe rând o jucărie o dată.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Joaca de-a casa, cu roluri$q$, array[$q$o cutie mare de carton sau o pătură peste masă; câteva obiecte de bucătărie$q$]::text[], 10, array[$q$Construiți împreună o „casă” din cutie sau pătură.$q$, $q$Întrebați: „Cine locuiește aici? Ce rol vrei tu? Ce rol am eu?”$q$, $q$Jucați scena aleasă de el (gătit, venirea unui musafir); voi intrați în rol și urmați regulile lui.$q$, $q$La final, întrebați: „Ce s-a întâmplat în povestea noastră?”$q$]::text[], $q$A împărțit rolurile și a condus cel puțin o scenă.$q$, $q$O problemă în joc: „S-a stricat ușa casei! Ce facem?”$q$, $q$Plan înainte de joc: el spune cine e fiecare și ce face, apoi jucați exact planul (după ghidul Harvard pentru 3–5 ani).$q$, null),
    ($q$s1-b23-z6-resurse$q$, $q$Frunza sau piatra în cutie$q$, array[$q$Aduceți o frunză sau o piatră în casă pe scurt.$q$, $q$Puneți-o în cutie: „Ajunge. La loc în cutie.”$q$, $q$Dacă vrea: alegeți să o lăsați afară în loc de cutie.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cutia comorilor din curte$q$, array[$q$o cutie de pantofi; 3–4 comori mari din curte$q$]::text[], 6, array[$q$Întrebați: „Ce comori păstrăm și ce lăsăm afară?”$q$, $q$Alege el 3 comori și spune de ce o păstrează pe fiecare.$q$, $q$Le aranjează în cutie după o regulă aleasă de el (mare–mic, după culoare).$q$, $q$Le duce afară pe cele care rămân: „Frunza udă rămâne afară, altfel…?”$q$]::text[], $q$A ales ce păstrează, cu un motiv, și a decis unde stă fiecare lucru.$q$, $q$Etichetă desenată: voi desenați pe cutie ce e înăuntru, el alege ce desen.$q$, $q$„Ce se întâmplă cu frunza în cutie, peste o săptămână?” Verificați duminica viitoare.$q$, $q$Fără ciuperci, bobițe sau pietricele mici.$q$),
    ($q$s1-b23-z7-mental$q$, $q$Locul favorit al săptămânii$q$, array[$q$Întrebați: „Unde ți-a plăcut cel mai mult?” — arătați 2–3 opțiuni.$q$, $q$Stați acolo un moment și numiți locul.$q$, $q$Dacă vrea: spuneți de ce e frumos, într-o frază scurtă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Povestim săptămâna cu harta și comorile$q$, array[$q$harta casei de vineri; cutia comorilor$q$]::text[], 10, array[$q$Așezați harta și comorile pe masă: „Ce am făcut săptămâna asta?”$q$, $q$El alege o comoară și povestește unde a găsit-o.$q$, $q$Întrebați: „Ce ți-a plăcut cel mai mult? De ce?”$q$, $q$Voi povestiți un moment, iar el completează ce ați uitat.$q$]::text[], $q$A povestit cel puțin 2 momente din săptămână, cu un motiv pentru favorit.$q$, $q$Momentele în ordine: „Ce a fost primul? Și pe urmă?”$q$, $q$„Ce vrei să facem săptămâna viitoare în curte?” Spune el un plan, iar voi îl notați pe hartă.$q$, null),
    ($q$s1-b23-z7-fizic$q$, $q$Plimbare liberă pe traseul cunoscut$q$, array[$q$El dictează ritmul pe un traseu scurt casă–curte.$q$, $q$Voi numiți ce arată, fără grabă.$q$, $q$Dacă vrea: reluați locul favorit al săptămânii 20 de secunde.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Plimbarea condusă de el$q$, array[$q$casa și curtea$q$]::text[], 10, array[$q$Spuneți: „Azi ești ghidul. Unde mergem?”$q$, $q$Conduce el traseul; voi întrebați la fiecare oprire: „Ce vedem aici?”$q$, $q$Se opresc la locul favorit al săptămânii, iar el spune de ce l-a ales.$q$, $q$Întoarcerea o face tot el, pe același drum.$q$]::text[], $q$A condus un traseu de cel puțin 3 opriri și a explicat alegerea locului favorit.$q$, $q$Un mod de mers ales de el pentru întoarcere.$q$, $q$„Pe ce drum ajungem cel mai repede la poartă?” Încercați două drumuri și comparați.$q$, null),
    ($q$s1-b23-z7-social$q$, $q$Ritual: bună seara, casă$q$, array[$q$Șoptiți: „Bună seara, casă.”$q$, $q$Îmbrățișați-vă doar dacă vrea; fără forțare.$q$, $q$Dacă vrea: adăugați: „Curte — la revedere până mâine.”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Bună seara, casă: ce mulțumim azi$q$, array[$q$lumină mică$q$]::text[], 4, array[$q$Stingeți lumina mare și spuneți încet: „Bună seara, casă.”$q$, $q$Întrebați: „Pentru ce mulțumim casei azi?” (că ne-a ținut de cald, pentru patul moale).$q$, $q$Spune el o mulțumire; voi spuneți una.$q$, $q$Îmbrățișare doar dacă vrea.$q$]::text[], $q$A spus o mulțumire, cu propoziția lui.$q$, $q$O mulțumire pentru un om din familie.$q$, $q$„Ce urăm curții pentru noaptea asta?” Inventează el urarea.$q$, null),
    ($q$s1-b23-z7-resurse$q$, $q$Totul la loc înainte de calm$q$, array[$q$Strângeți împreună un obiect sau două: „La loc.”$q$, $q$Spuneți: „Gata. Acum e liniște.”$q$, $q$Dacă vrea: alegeți un obiect favorit să rămână la vedere.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Strânsul de duminică: el face planul$q$, array[$q$4–6 lucruri rămase prin casă$q$]::text[], 6, array[$q$Întrebați: „Ce trebuie strâns înainte de somn? Cu ce începem?”$q$, $q$Strânge el după planul lui; voi ajutați la ce e greu.$q$, $q$Alege un obiect favorit care rămâne la vedere și spune de ce.$q$, $q$Verificați împreună: „E totul la loc?”$q$]::text[], $q$A făcut un plan de strâns în 2–3 pași și l-a dus la capăt.$q$, $q$Împarte sarcinile: „Tu strângi cărțile, eu strâng cuburile.”$q$, $q$Estimare: „Cât crezi că durează? Cât un cântec sau două?” Verificați.$q$, null),
    ($q$s2-b23-z1-mental$q$, $q$Apa curge — etichete bogate$q$, array[$q$Deschideți un fir subțire: „Apă. Curge. Rece.”$q$, $q$Spuneți: „Apă.” și arătați firul.$q$, $q$Dacă vrea: întrebați: „Unde se duce apa?” și arătați scurgerea.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Drumul apei: de unde vine, unde se duce$q$, array[$q$robinetul; un vas; un prosop$q$]::text[], 10, array[$q$Deschideți un fir subțire și întrebați: „De unde crezi că vine apa?” Ascultați orice idee.$q$, $q$Spuneți simplu: „Vine prin țevi, de la fântână.” Arătați țeava de sub chiuvetă.$q$, $q$Puneți dopul și lăsați să se strângă puțină apă: „Ce se întâmplă dacă scoatem dopul?”$q$, $q$Scoate el dopul și privesc cum se scurge: „Unde s-a dus?”$q$]::text[], $q$A făcut o presupunere despre de unde vine sau unde se duce apa și a verificat cu dopul.$q$, $q$Vârtejul: „De ce se învârte apa când se scurge?” Ascultați explicația lui, fără să o corectați.$q$, $q$„Unde mai merge apa din casă?” Căutați împreună: baia, mașina de spălat, burlanul din curte.$q$, $q$Doar apă rece sau călduță; robinetul îl deschide adultul.$q$),
    ($q$s2-b23-z1-fizic$q$, $q$Pași până la robinet$q$, array[$q$Mergeți împreună până la chiuvetă.$q$, $q$Arătați: „Aici e apa.” Faceți un pas pe loc.$q$, $q$Dacă vrea: alegeți chiuveta din baie sau din bucătărie.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cu paharul plin până la robinet și înapoi$q$, array[$q$un pahar de plastic; o tavă; prosop$q$]::text[], 8, array[$q$Umpleți paharul pe jumătate; el îl duce de la chiuvetă la masă, fără să verse.$q$, $q$Întrebați: „Cum ai făcut să nu verși?” (încet, cu două mâini).$q$, $q$Încă o dată, cu paharul pe tavă.$q$, $q$Comparați: „Cu tava sau fără, ce a fost mai ușor?”$q$]::text[], $q$A dus paharul pe jumătate plin cel puțin o dată fără să verse și a explicat cum.$q$, $q$Paharul mai plin: „Până la semnul acesta.”$q$, $q$Un drum cu o cotitură (pe după scaun): „Cum faci la colț?”$q$, $q$Pahar de plastic; podeaua ștearsă imediat.$q$),
    ($q$s2-b23-z1-social$q$, $q$Arătăm apa adultului$q$, array[$q$Invitați-l să arate paharul cuiva din casă.$q$, $q$Spuneți: „Uite apa!”$q$, $q$Dacă vrea: el alege cui arată — mama, tata sau bunica (dacă e).$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Barmanul familiei$q$, array[$q$o carafă mică; 3 pahare de plastic; o tavă$q$]::text[], 8, array[$q$Întreabă el pe fiecare: „Vrei apă? Multă sau puțină?”$q$, $q$Ține minte răspunsurile (2–3 persoane).$q$, $q$Toarnă din carafă cât a cerut fiecare (cu ajutor la carafă, dacă e grea).$q$, $q$Duce paharele și spune: „Poftim, apa ta.”$q$]::text[], $q$A ținut minte ce a cerut fiecare și a dus paharele la persoanele potrivite.$q$, $q$O persoană spune „nu, mulțumesc”: „Câte pahare ne trebuie acum?”$q$, $q$Cererea cu condiție: „Eu vreau apă doar dacă e rece.” Verifică el temperatura și decide.$q$, $q$Carafă ușoară, de plastic sau metal; fără sticlă.$q$),
    ($q$s2-b23-z1-resurse$q$, $q$Pahar: ajunge puțin$q$, array[$q$Turnați puțin: „Ajunge atâta.”$q$, $q$Arătați: „Nu mai turnăm.”$q$, $q$Dacă vrea: alegeți pahar mic sau pahar mare pentru puțină apă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Câtă apă ne trebuie?$q$, array[$q$3 pahare de mărimi diferite; o carafă$q$]::text[], 6, array[$q$Întrebați: „Ți-e sete puțin sau tare? Ce pahar alegi?”$q$, $q$Toarnă el puțin și bea. „Mai vrei?”$q$, $q$Dacă mai rămâne apă, întrebați: „Ce facem cu ce a rămas?” (udăm floarea, nu o aruncăm).$q$, $q$Spune el regula: „Turnăm cât bem.”$q$]::text[], $q$A ales paharul după cât de sete îi e și a decis ce face cu apa rămasă.$q$, $q$Comparați: „Câte pahare mici încap într-unul mare?” Verificați turnând.$q$, $q$„De ce nu lăsăm robinetul să curgă degeaba?” Ascultați motivele lui, apoi spuneți simplu: „Apa din fântână se poate termina.”$q$, null),
    ($q$s2-b23-z2-mental$q$, $q$Gol și plin$q$, array[$q$Arătați paharul gol: „Gol.”$q$, $q$Turnați puțin: „Plin puțin.” Comparați.$q$, $q$Dacă vrea: el alege: „Vrei gol sau plin?” pe pahar.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Gol, puțin, jumătate, plin: în ordine$q$, array[$q$4 pahare transparente identice; o carafă; colorant alimentar (opțional)$q$]::text[], 10, array[$q$Umple el paharele: unul gol, unul cu puțin, unul pe jumătate, unul plin.$q$, $q$Le amestecați, iar el le pune în ordine, de la gol la plin.$q$, $q$Întrebați: „Unde e cea mai multă apă? Dar cea mai puțină?”$q$, $q$Voi mutați un pahar din rând: „Ce s-a schimbat?”$q$]::text[], $q$A ordonat singur cele 4 pahare și a spus unde e cel mai mult.$q$, $q$„Fă-le pe toate la fel!” Mută el apa dintre pahare până arată la fel.$q$, $q$Un pahar înalt și subțire și unul scund și lat, cu aceeași cantitate: „Unde e mai multă apă?” Turnați apoi în două pahare identice și verificați. (E normal ca la vârsta asta să spună că în cel înalt e mai multă.)$q$, null),
    ($q$s2-b23-z2-fizic$q$, $q$Turnăm cu grijă în vas$q$, array[$q$Țineți mâna lui pe pahar și turnați puțin în vas.$q$, $q$Spuneți: „Încet. Turnăm.”$q$, $q$Dacă vrea: încă o turnare mică, apoi gata.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Turnăm până la linie$q$, array[$q$o cană mică de turnat; 3 pahare transparente cu câte un elastic la înălțimi diferite; tavă; burete$q$]::text[], 8, array[$q$Puneți elasticul pe un pahar, la jumătate: „Turnăm până aici, nu mai sus.”$q$, $q$El toarnă încet; voi spuneți „încet… încet… stop!” prima dată.$q$, $q$A doua oară se oprește singur la linie.$q$, $q$Dacă varsă, șterge el cu buretele: „Ce facem data viitoare?”$q$]::text[], $q$S-a oprit singur la linie cel puțin o dată.$q$, $q$Trei pahare cu linii la înălțimi diferite: „puțin”, „jumătate”, „plin”.$q$, $q$Turnat dintr-o carafă în două pahare, egal: „Acum fiecare are la fel?”$q$, null),
    ($q$s2-b23-z2-social$q$, $q$Beau cu tine pe rând$q$, array[$q$Beți voi o înghițitură: „Acum eu.”$q$, $q$Oferiți: „Acum tu” — fără forțare.$q$, $q$Dacă vrea: încă un schimb de rând.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Picnicul cu apă pentru jucării$q$, array[$q$3 jucării; pahare mici de plastic; o carafă mică$q$]::text[], 10, array[$q$Spuneți: „Jucăriile au venit la picnic și le e sete.”$q$, $q$El le întreabă pe rând (voi le dați glas): „Ursule, vrei apă?”$q$, $q$Ursul răspunde: „Da, dar puțină.” Iepurele: „Eu vreau multă.” El toarnă după cerere.$q$, $q$La final, întrebați: „Cine a primit cea mai multă apă?”$q$]::text[], $q$A turnat după cerere pentru cel puțin 2 jucării și a comparat cantitățile.$q$, $q$O jucărie e supărată că a primit mai puțin: „Ce facem?”$q$, $q$Apa se termină în carafă: „Mai sunt două jucării. Cum împărțim ce a rămas?”$q$, null),
    ($q$s2-b23-z2-resurse$q$, $q$Udăm planta — ajunge$q$, array[$q$Turnați puțin la rădăcină: „Dăm apă. Ajunge.”$q$, $q$Opriți-vă: „Gata udatul.”$q$, $q$Dacă vrea: ștergeți o picătură de pe masă împreună.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Câtă apă vrea planta?$q$, array[$q$2 plante în ghiveci; o cană mică; un deget de verificat pământul$q$]::text[], 8, array[$q$Pune el degetul în pământ la fiecare plantă: „E uscat sau ud?”$q$, $q$Decide care plantă are nevoie de apă.$q$, $q$Toarnă puțin, încet, la rădăcină. Se oprește când apa începe să iasă în farfurioară.$q$, $q$Întrebați: „De ce ne-am oprit? Ce se întâmplă dacă turnăm prea mult?”$q$]::text[], $q$A verificat pământul și a decis singur care plantă primește apă.$q$, $q$Comparați o plantă udată acum cu una udată ieri: „Care e mai udă?”$q$, $q$Experiment pe o săptămână: două fire de grâu sau fasole într-un pahar, unul udat și unul nu. Verificați duminica.$q$, null),
    ($q$s2-b23-z3-mental$q$, $q$Ud sau uscat?$q$, array[$q$Atingeți ambele: „Ud. Uscat.”$q$, $q$Spuneți: „Ud.” pe cârpa udă.$q$, $q$Dacă vrea: ascundeți una și întrebați: „Unde e cea udă?”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ce absoarbe apa?$q$, array[$q$o tavă cu puțină apă; burete, cârpă, hârtie, folie de plastic, lingură de metal, frunză$q$]::text[], 10, array[$q$Întrebați la fiecare obiect: „Crezi că ia apa sau nu?”$q$, $q$Pune el obiectul în apă și îl ridică: „A luat apă?”$q$, $q$Sortează în două grămezi: „ia apa” și „nu ia apa”.$q$, $q$Întrebați: „Cu ce ștergem masa? De ce nu cu folia?”$q$]::text[], $q$A prezis și a verificat cel puțin 4 obiecte, apoi le-a sortat după rezultat.$q$, $q$Cine ia cea mai multă apă: stoarceți fiecare obiect într-un pahar și comparați.$q$, $q$„Avem apă vărsată pe jos. Ce alegi din toate obiectele?” Explică alegerea și încearcă.$q$, null),
    ($q$s2-b23-z3-fizic$q$, $q$Stropi pe mână$q$, array[$q$Udați ușor dosul mâinii: „Ud. Rece.”$q$, $q$Ștergeți împreună: „Uscat.”$q$, $q$Dacă vrea: repetați pe cealaltă mână.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Stoarcem buretele$q$, array[$q$un burete mare; două boluri, unul cu apă$q$]::text[], 6, array[$q$Înmoaie el buretele în bolul cu apă și îl stoarce în bolul gol.$q$, $q$Întrebați: „Câte stoarceri până mutăm toată apa?” Numărați împreună.$q$, $q$Comparați: cu o mână și cu două mâini.$q$, $q$La final, întrebați: „Ce ai simțit în mâini?”$q$]::text[], $q$A mutat apa dintr-un bol în altul prin stoarcere, de cel puțin 4 ori.$q$, $q$Stoarce până la linia de pe bolul gol.$q$, $q$Cu un burete mic și unul mare: „Cu care terminăm mai repede? De ce?”$q$, null),
    ($q$s2-b23-z3-social$q$, $q$Mulțumesc pentru apă$q$, array[$q$După ce bea (sau voi beți), modelați: „Mulțumesc.”$q$, $q$Așteptați imitația fără presiune.$q$, $q$Dacă vrea: el oferă paharul gol înapoi pe masă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Mulțumesc, poftim, te rog: la masă cu apa$q$, array[$q$carafa; paharele familiei$q$]::text[], 5, array[$q$La masă, modelați: „Îmi dai, te rog, apa?”$q$, $q$El cere apa cu „te rog” și mulțumește când o primește.$q$, $q$Apoi el oferă: „Mai vrea cineva apă?”$q$, $q$Întrebați: „Cum te simți când cineva îți spune mulțumesc?”$q$]::text[], $q$A cerut cu „te rog”, a mulțumit și a oferit apă cuiva.$q$, $q$Formule noi: „Cu plăcere”, „Poftim”.$q$, $q$Scenă jucată cu jucăriile: ursul ia apa fără să ceară. „Ce-i spunem ursului? Cum ar fi trebuit să ceară?”$q$, null),
    ($q$s2-b23-z3-resurse$q$, $q$Ștergem picătura — prosopul la loc$q$, array[$q$Ștergeți o picătură împreună: „Ștergem.”$q$, $q$Puneți prosopul pe cârlig: „Prosopul la loc.”$q$, $q$Dacă vrea: alegeți cârligul sau spătarul scaunului.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Masa udă: cum o ștergem bine?$q$, array[$q$puțină apă vărsată intenționat; burete; cârpă; prosop de hârtie$q$]::text[], 5, array[$q$„S-a vărsat apa. Ce facem întâi?” Lăsați-l să propună.$q$, $q$Șterge el cu ce a ales.$q$, $q$Întrebați: „E uscat acum? Cum verificăm?” (cu palma).$q$, $q$Pune el cârpa la uscat și spune unde.$q$]::text[], $q$A șters masa, a verificat cu palma și a pus cârpa la uscat.$q$, $q$Ordinea: întâi buretele pentru multă apă, apoi cârpa pentru ce rămâne.$q$, $q$„Dacă vărsăm suc, nu apă, ce mai facem în plus?” (ștergem cu apă, ca să nu fie lipicios).$q$, null),
    ($q$s2-b23-z4-mental$q$, $q$Unde e apa în casă?$q$, array[$q$Arătați două locuri cu apă: chiuvetă și pahar (sau plantă).$q$, $q$Întrebați: „Unde mai e apă?”$q$, $q$Dacă vrea: comparați: „Aici e multă. Aici e puțină.”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Turul apei prin casă și curte$q$, array[$q$un carton cu pătrate pentru desene; creion$q$]::text[], 10, array[$q$Întrebați: „Unde e apă în casa noastră?” Faceți lista împreună, din memorie.$q$, $q$Mergeți în tur să verificați fiecare loc. Voi desenați un semn mic pentru fiecare (robinet, cadă, floare).$q$, $q$Întrebați: „Unde e cea mai multă apă? Dar cea mai puțină?”$q$, $q$Adăugați un loc la care nu v-ați gândit (câinele are un bol cu apă).$q$]::text[], $q$A numit din memorie cel puțin 3 locuri cu apă și le-a verificat.$q$, $q$Apa pe care n-o vedem: în fructe (strângeți o felie de portocală), în frunze.$q$, $q$„Unde e apă în curte după ploaie, dar nu și când e soare?” (băltoace, rouă).$q$, null),
    ($q$s2-b23-z4-fizic$q$, $q$Cărăm paharul gol$q$, array[$q$Cărați împreună paharul gol 5–8 pași.$q$, $q$Spuneți: „Tu porți paharul.”$q$, $q$Dacă vrea: alegeți traseul — spre masă sau spre chiuvetă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cursa cu găletușa$q$, array[$q$o găletușă cu puțină apă; un lighean gol în curte$q$]::text[], 10, array[$q$Duce el apă cu găletușa de la robinetul de afară la ligheanul gol, la 5–6 metri.$q$, $q$Întrebați: „De câte drumuri e nevoie ca să umplem până la linie?”$q$, $q$Lasă-l să încerce să meargă mai repede: „Ce se întâmplă când alergi?”$q$, $q$Comparați ce a rămas în găletușă după un drum încet și după unul repede.$q$]::text[], $q$A cărat apă de mai multe ori și a observat diferența dintre mers încet și repede.$q$, $q$Cu un pahar în loc de găletușă: „Care e mai bun pentru cărat apa?”$q$, $q$Problema găurii: o găletușă cu o gaură mică în fund. „Cum aducem totuși apă?”$q$, $q$Ligheanul gol după joc; un adult lângă el tot timpul lângă apă.$q$),
    ($q$s2-b23-z4-social$q$, $q$Împărțim o înghițitură$q$, array[$q$Beți voi, apoi oferiți: „Rândul tău.”$q$, $q$Fără forțare dacă refuză.$q$, $q$Dacă vrea: inventați regula: „Întâi tu, apoi eu.”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cine ce bea? Ancheta familiei$q$, array[$q$niciunul$q$]::text[], 6, array[$q$El întreabă pe fiecare din casă: „Ce-ți place să bei?”$q$, $q$Ține minte răspunsurile și vi le spune la final.$q$, $q$Întrebați: „Cine bea același lucru?”$q$, $q$La masa de seară, servește fiecăruia băutura preferată (cu ajutor).$q$]::text[], $q$A întrebat cel puțin 2 persoane și și-a amintit răspunsurile.$q$, $q$Întrebare în plus: „Rece sau caldă?”$q$, $q$Răspuns neașteptat (bunica spune „ceai de mentă”): „Avem? Dacă nu, ce-i oferim în schimb?”$q$, null),
    ($q$s2-b23-z4-resurse$q$, $q$Paharul la loc pe masă$q$, array[$q$Luați paharul.$q$, $q$Puneți-l pe masă: „La loc. Masă.”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Paharul fiecăruia$q$, array[$q$paharele familiei, de culori diferite$q$]::text[], 5, array[$q$Fiecare om are un pahar de altă culoare. Întrebați: „Al cui e paharul verde?”$q$, $q$Pune el paharele la locul fiecăruia pe masă.$q$, $q$După masă, le duce la chiuvetă.$q$, $q$Întrebați: „De ce e bine ca fiecare să aibă paharul lui?”$q$]::text[], $q$A pus paharele la locurile potrivite și le-a strâns după masă.$q$, $q$Paharul lipsă: „Câte pahare sunt și câți suntem?”$q$, $q$„Vine un musafir. Ce culoare îi dăm, ca să nu se încurce?”$q$, null),
    ($q$s2-b23-z5-mental$q$, $q$Ascultăm apa$q$, array[$q$Deschideți un fir: „Auzi apa?”$q$, $q$Închideți: „Liniște. Apa s-a oprit.”$q$, $q$Dacă vrea: întrebați: „Vrei să o auzim iar?”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Apa cântă: sunete de apă$q$, array[$q$robinetul; un pahar de metal; un bol de plastic; o sticlă$q$]::text[], 8, array[$q$Lăsați să curgă un fir subțire în pahar, apoi în bol: „Sună la fel?”$q$, $q$Umpleți sticla sub robinet: „Ascultă cum se schimbă sunetul pe măsură ce se umple.”$q$, $q$Închide el ochii: „Curge în pahar sau în bol?”$q$, $q$Întrebați: „Ce sunet face ploaia? Dar marea?”$q$]::text[], $q$A recunoscut cu ochii închiși cel puțin o dată în ce vas curge apa.$q$, $q$Fir subțire și fir gros: „Care sună mai tare?”$q$, $q$„Cum știm că sticla e aproape plină, fără să ne uităm?” (sunetul devine mai subțire). Verificați.$q$, null),
    ($q$s2-b23-z5-fizic$q$, $q$Deget pe urma de apă pe geam$q$, array[$q$Dacă e umed pe geam sau stropiți ușor, trasați cu degetul.$q$, $q$Mișcați brațul: „Urme de apă.”$q$, $q$Dacă vrea: desenați un cerc sau o linie împreună.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Desene cu apă pe gard$q$, array[$q$o pensulă mare; un pahar cu apă; gardul sau peretele de beton din curte$q$]::text[], 10, array[$q$Desenează el cu apă pe beton: o linie, un cerc, ce vrea.$q$, $q$Întrebați: „Ce se întâmplă cu desenul după un minut?”$q$, $q$Faceți un desen la soare și unul la umbră: „Care dispare mai repede?”$q$, $q$Verificați după câteva minute.$q$]::text[], $q$A observat că apa dispare și a comparat soarele cu umbra.$q$, $q$Desenați după instrucțiune: „O linie lungă, apoi una scurtă, apoi un cerc.”$q$, $q$„De ce a dispărut desenul? Unde s-a dus apa?” Acceptați ideile lui, apoi spuneți: „S-a uscat, a plecat în aer.”$q$, $q$Pălărie dacă e soare puternic.$q$),
    ($q$s2-b23-z5-social$q$, $q$Arătăm paharul cuiva drag$q$, array[$q$Arătați paharul unei persoane dragi 1–2 minute.$q$, $q$Salut scurt: „Bună! Uite apa.”$q$, $q$Dacă vrea: el ține paharul când arată.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Dăm apă păsărilor$q$, array[$q$un vas lat și puțin adânc; o piatră mare în mijloc$q$]::text[], 8, array[$q$Întrebați: „Cine bea apă în curtea noastră, în afară de noi?”$q$, $q$Pregătiți împreună un bol pentru păsări: apă puțină, o piatră pe care să stea.$q$, $q$El alege locul: „Unde îl punem, ca să-l vadă păsările, dar să nu le prindă pisica?”$q$, $q$Verificați a doua zi: „A venit cineva?”$q$]::text[], $q$A ales locul bolului cu un motiv.$q$, $q$Schimbă el apa a doua zi.$q$, $q$„Cum aflăm ce păsări vin, fără să le speriem?” (ne uităm pe geam, stăm liniștiți).$q$, null),
    ($q$s2-b23-z5-resurse$q$, $q$Oprim robinetul — gata$q$, array[$q$Închideți împreună robinetul: „Oprit. Gata.”$q$, $q$Arătați că nu mai curge.$q$, $q$Dacă vrea: el „ajută” să apese mânerul cu mâna voastră peste a lui.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Robinetul: puțin, mult, oprit$q$, array[$q$robinetul de la chiuvetă$q$]::text[], 5, array[$q$Deschideți voi robinetul puțin, apoi mai mult: „Puțin. Mult.”$q$, $q$Mâna lui pe mâna voastră, închideți: „Oprit.”$q$, $q$Întrebați: „Când lăsăm apa să curgă și când o oprim?”$q$, $q$La spălatul mâinilor: închide el robinetul cât se săpunește.$q$]::text[], $q$A închis robinetul cât s-a săpunit, cu propria idee sau la întrebare.$q$, $q$Regula spusă de el: „Mă săpunesc cu apa oprită.”$q$, $q$Detectivul de picături: ascultați seara dacă picură vreun robinet. „Ce facem dacă picură?”$q$, $q$Robinetul de apă caldă îl folosește doar adultul.$q$),
    ($q$s2-b23-z6-mental$q$, $q$Nor sau soare — legat de apă$q$, array[$q$Arătați cerul: „Nor.” sau „Soare.”$q$, $q$Legătura: „Din nori vine apa.” (simplu, o frază).$q$, $q$Dacă vrea: întrebați: „Crezi că e ud sau uscat afară?”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Nori, ploaie, băltoace: ce se leagă de ce?$q$, array[$q$fereastra; o carte cu vremea (opțional)$q$]::text[], 8, array[$q$Priviți cerul: „Ce fel de nori sunt? Albi sau gri?”$q$, $q$Întrebați: „Când sunt nori gri, ce poate veni?”$q$, $q$Legați: „Ploaia face… băltoace. Soarele usucă… băltoacele.”$q$, $q$Spune el lanțul în cuvintele lui.$q$]::text[], $q$A făcut cel puțin o legătură de tip „când…, atunci…” despre vreme și apă.$q$, $q$Prognoza lui: „Crezi că plouă azi?” Verificați seara.$q$, $q$„Unde se duc băltoacele când nu mai sunt?” Acceptați ideile lui; marcați o băltoacă cu bețe și verificați a doua zi.$q$, null),
    ($q$s2-b23-z6-fizic$q$, $q$Apă afară: baltă sau iarbă udă$q$, array[$q$Dacă e ud afară, pășiți lângă baltă sau pe iarbă umedă (nu în adânc).$q$, $q$Spuneți: „Apă jos. Ud afară.”$q$, $q$Dacă vrea: alegeți unde pășiți — lângă baltă sau pe iarbă uscată.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Băltoaca: săritură, măsurătoare, desen$q$, array[$q$cizme; o băltoacă (sau una făcută cu o găleată pe pământ); un băț$q$]::text[], 10, array[$q$Sare el în băltoacă și privește stropii: „Unde au ajuns?”$q$, $q$Măsurați băltoaca cu pași: „Câți pași are?”$q$, $q$Desenați cu bățul conturul ei pe pământ.$q$, $q$Întrebați: „Mâine va fi mai mare sau mai mică?”$q$]::text[], $q$A măsurat băltoaca cu pași și a făcut o predicție.$q$, $q$Săritură mică și săritură mare: „Care face stropi mai mari?”$q$, $q$Verificarea de a doua zi: comparați cu conturul desenat și explică el ce s-a întâmplat.$q$, $q$Doar băltoace mici, fără apă adâncă; haine de schimb.$q$),
    ($q$s2-b23-z6-social$q$, $q$Joacă lângă adult la apă$q$, array[$q$Voi turnați puțin; el stă lângă și observă.$q$, $q$Comentați ce face el, fără a prelua jocul.$q$, $q$Dacă vrea: un schimb — el toarnă o dată cu mâna voastră.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Atelierul de apă, împreună$q$, array[$q$un lighean cu puțină apă; pahare, pâlnie, burete, lingură$q$]::text[], 10, array[$q$Spuneți: „Facem un proiect împreună: umplem sticla asta.”$q$, $q$Împărțiți rolurile: el ține pâlnia, voi turnați; apoi schimbați.$q$, $q$Discutați ce nu merge: „Curge pe lângă. Ce facem?”$q$, $q$La final: „Cum am lucrat împreună?”$q$]::text[], $q$A lucrat cu voi la un scop comun, cu rolurile schimbate cel puțin o dată.$q$, $q$El dă instrucțiunile: „Toarnă mai încet!”$q$, $q$Problema fără pâlnie: „Cum umplem sticla cu gât îngust fără pâlnie?” (o hârtie făcută sul, o lingură).$q$, $q$Adultul stă lângă lighean tot timpul.$q$),
    ($q$s2-b23-z6-resurse$q$, $q$Două frunze ude în cutie$q$, array[$q$Luați două frunze (ude dacă se poate): „Una. Două.”$q$, $q$Puneți-le în cutie: „La loc. Ajunge.”$q$, $q$Dacă vrea: comparați o frunză udă cu una uscată.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Frunzele ude și frunzele uscate$q$, array[$q$4 frunze mari, 2 ude și 2 uscate; o cutie; un prosop$q$]::text[], 6, array[$q$Întrebați: „Care sunt ude? Cum știi?”$q$, $q$Sortează el.$q$, $q$Puneți o frunză udă pe prosop, la soare: „Ce se întâmplă cu ea până diseară?”$q$, $q$Seara verificați: „E tot udă?”$q$]::text[], $q$A sortat frunzele ude și uscate și a verificat ce s-a întâmplat cu cea lăsată la soare.$q$, $q$Două frunze ude: una la soare, una la umbră. Care se usucă prima?$q$, $q$„Cum uscăm repede o frunză udă?” Încercați ideea lui (o ștergem, o punem la vânt).$q$, null),
    ($q$s2-b23-z7-mental$q$, $q$Carte sau imagine cu apă$q$, array[$q$Răsfoiți împreună; el întoarce pagina dacă vrea.$q$, $q$Când vedeți apă: „Apă.”$q$, $q$Dacă vrea: spuneți: „Apă.” pe pagina aleasă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Povestea apei din săptămâna asta$q$, array[$q$o carte cu apă; obiectele din săptămână (burete, pahare)$q$]::text[], 10, array[$q$Așezați obiectele pe masă: „Ce am făcut cu fiecare?”$q$, $q$El alege un obiect și povestește.$q$, $q$Citiți cartea și întrebați la fiecare pagină: „Ce crezi că urmează?”$q$, $q$Întrebați: „Ce ți-a plăcut cel mai mult cu apa? De ce?”$q$]::text[], $q$A povestit cel puțin 2 activități ale săptămânii și a ghicit ce urmează în carte.$q$, $q$Ordinea: „Ce am făcut mai întâi, luni? Dar vineri?”$q$, $q$Inventați împreună o poveste: „O picătură pleacă din nor…” El continuă fiecare frază.$q$, null),
    ($q$s2-b23-z7-fizic$q$, $q$Plimbare liberă — unde e apa?$q$, array[$q$El dictează ritmul în casă sau curte.$q$, $q$Dacă arată apă (pahar, plantă, baltă), numiți-o.$q$, $q$Dacă vrea: opriți-vă la locul cu apă favorit al săptămânii.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Plimbarea apei: el e ghidul$q$, array[$q$curtea$q$]::text[], 10, array[$q$Spuneți: „Arată-mi toate locurile cu apă din curte.”$q$, $q$Conduce el; la fiecare loc spune ce e acolo.$q$, $q$Întrebați: „Unde a fost apă săptămâna asta și acum nu mai e?”$q$, $q$Se opresc la locul favorit; spune el de ce.$q$]::text[], $q$A condus turul și a găsit cel puțin 2 locuri cu apă.$q$, $q$Locul ascuns: rouă pe iarbă dimineața, apă în scorbură.$q$, $q$„Unde ar trebui să punem un butoi pentru apa de ploaie? De ce acolo?” (sub burlan).$q$, null),
    ($q$s2-b23-z7-social$q$, $q$Noapte bună după apă$q$, array[$q$Spuneți: „Noapte bună.” după ritualul de apă/mâini.$q$, $q$Lumină mică, calm, fără grabă.$q$, $q$Dacă vrea: reamintiți locul favorit cu apă din săptămână.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Noapte bună, cu o mulțumire pentru apă$q$, array[$q$lumină mică$q$]::text[], 4, array[$q$După spălat, spuneți încet: „Noapte bună.”$q$, $q$Întrebați: „Pentru ce am folosit azi apa?”$q$, $q$Spune el un lucru; voi altul.$q$, $q$„Mulțumim, apă.” Îmbrățișare doar dacă vrea.$q$]::text[], $q$A spus cel puțin un lucru pentru care am folosit apa azi.$q$, $q$Cine a mai primit apă azi (planta, păsările)?$q$, $q$„Ce am face fără apă o zi întreagă?” Discuție scurtă, liniștită.$q$, null),
    ($q$s2-b23-z7-resurse$q$, $q$Prosopul la loc — ritual$q$, array[$q$După mâini sau baie: prosopul pe cârlig.$q$, $q$„La loc. Gata.”$q$, $q$Dacă vrea: alegeți prosopul colorat preferat pentru mâine.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Prosoapele familiei$q$, array[$q$prosoapele familiei, pe cârlige$q$]::text[], 5, array[$q$Întrebați: „Al cui e fiecare prosop?”$q$, $q$Agață el prosopul lui și al încă cuiva.$q$, $q$Verifică dacă vreunul e ud: „Pe care îl punem la uscat?”$q$, $q$Întrebați: „De ce nu împăturim prosopul ud?”$q$]::text[], $q$A agățat cel puțin 2 prosoape și a recunoscut unul ud.$q$, $q$Împăturire simplă a unui prosop uscat, în două.$q$, $q$„Ce se întâmplă cu un prosop ud lăsat strâns grămadă?” Verificați cu o cârpă mică până a doua zi (miros, umezeală).$q$, null),
    ($q$s3-b23-z1-mental$q$, $q$Aproape și departe$q$, array[$q$Faceți un sunet aproape: „Aproape.”$q$, $q$Un sunet mai departe: „Departe.”$q$, $q$Dacă vrea: spuneți: „Ascultăm. Ascultă.” înainte de al doilea sunet.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Aproape sau departe? Ghicim cu urechile$q$, array[$q$un clopoțel sau o jucărie sonoră; două camere alăturate$q$]::text[], 8, array[$q$El închide ochii. Voi sunați clopoțelul aproape, apoi departe: „Aproape sau departe?”$q$, $q$Schimbați rolurile: el sună, voi ghiciți.$q$, $q$Întrebați: „De unde vine sunetul? Arată cu mâna.”$q$, $q$Încheiați: „Cum ai știut că e departe?” (mai încet).$q$]::text[], $q$A ghicit corect aproape sau departe de cel puțin 3 ori și a explicat cum.$q$, $q$Direcția: „Din stânga, din dreapta, din spate?” (doar arătat, fără etichete obligatorii).$q$, $q$Clopoțelul ascuns în cameră, el îl găsește după sunet, apropiindu-se.$q$, null),
    ($q$s3-b23-z1-fizic$q$, $q$Urechi afară două minute$q$, array[$q$Ieșiți scurt; stați pe loc și ascultați aproximativ 1–2 minute. Pe balcon, țineți-l de mână.$q$, $q$Arătați urechea: „Ascultăm.”$q$, $q$Dacă vrea: alegeți unde stați — lângă ușă sau mai departe.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Harta sunetelor din curte$q$, array[$q$curtea; o pătură$q$]::text[], 10, array[$q$Stați întinși pe pătură, cu ochii închiși, un minut.$q$, $q$Ridicați câte un deget pentru fiecare sunet auzit.$q$, $q$Spune el sunetele și de unde vin; mergeți spre unul dintre ele.$q$, $q$Întrebați: „Care sunet a fost cel mai aproape? Dar cel mai departe?”$q$]::text[], $q$A numit cel puțin 3 sunete și a mers spre sursa unuia.$q$, $q$Sunetele ordonate de la cel mai tare la cel mai încet.$q$, $q$„Ce sunet ai auzi dacă ar ploua acum? Dar noaptea?” Imaginează el.$q$, $q$Pe balcon sau lângă poartă, țineți-l de mână.$q$),
    ($q$s3-b23-z1-social$q$, $q$Joacă liniște–sunet o rundă$q$, array[$q$Spuneți: „Acum liniște” — 5 secunde.$q$, $q$Apoi: „Acum sunet” — o bătaie din palme împreună.$q$, $q$Dacă vrea: încă o rundă; el alege cine începe.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Liniștea și sunetul, cu dirijor$q$, array[$q$niciunul sau o tobă$q$]::text[], 6, array[$q$Regula: când dirijorul ridică mâna, toată lumea tace; când o coboară, facem zgomot.$q$, $q$Voi sunteți dirijorul primele runde.$q$, $q$Apoi el devine dirijorul.$q$, $q$Încheiați: „A fost greu să taci? Ce te-a ajutat?”$q$]::text[], $q$A respectat liniștea la semnal și a fost dirijor cel puțin o rundă.$q$, $q$Un al treilea semn: mâna în lateral înseamnă „șoptim”.$q$, $q$Regula pe dos: mâna sus înseamnă zgomot, jos liniște.$q$, null),
    ($q$s3-b23-z1-resurse$q$, $q$Oprim jucăria — gata$q$, array[$q$Lăsați un sunet scurt, apoi opriți: „Gata. Liniște.”$q$, $q$Puneți jucăria în cutie: „La loc.”$q$, $q$Dacă vrea: el apasă butonul de oprire cu ajutor.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Oprim când vrem, nu când se termină$q$, array[$q$o jucărie sonoră cu buton$q$]::text[], 5, array[$q$Întrebați: „Câte sunete vrei să asculți? Două sau trei?”$q$, $q$Pornește el și oprește exact la numărul ales.$q$, $q$Pune jucăria în cutie.$q$, $q$Întrebați: „Când e bine să oprim jucăria?” (când doarme cineva, la masă).$q$]::text[], $q$A oprit jucăria la numărul de sunete stabilit dinainte.$q$, $q$Un sunet scurt și unul lung, după comandă.$q$, $q$„Bunica doarme. Cum ne jucăm acum?” Propune el o variantă liniștită.$q$, null),
    ($q$s3-b23-z2-mental$q$, $q$Numește două sunete$q$, array[$q$Ascultați în casă: numiți două sunete (voce, apă, ușă).$q$, $q$Arătați sursa fiecăruia.$q$, $q$Dacă vrea: adăugați: „Tare.” pe sunetul mai puternic.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ce sunet a fost? Memorie de sunete$q$, array[$q$4 surse de sunet din casă (ușa, robinetul, un clopoțel, hârtie mototolită)$q$]::text[], 10, array[$q$El ascultă cu ochii închiși 2 sunete, unul după altul.$q$, $q$Spune ce a auzit și în ce ordine.$q$, $q$Creșteți la 3 sunete.$q$, $q$Apoi el face sunetele, iar voi ghiciți.$q$]::text[], $q$A spus în ordine cel puțin 2 sunete auzite cu ochii închiși.$q$, $q$3 sunete în ordine.$q$, $q$4 sunete, sau ordinea inversă: „Spune-le de la ultimul la primul.”$q$, null),
    ($q$s3-b23-z2-fizic$q$, $q$Bătăi din palme și calm$q$, array[$q$Bateți din palme de 2–4 ori împreună.$q$, $q$Apoi mâinile pe genunchi: „Calm.”$q$, $q$Dacă vrea: el alege câte bătăi — două sau patru.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ritmul: bate ce bat eu$q$, array[$q$palmele; o tobă sau o oală întoarsă$q$]::text[], 8, array[$q$Bateți voi un ritm scurt (lung, scurt, scurt); el îl repetă.$q$, $q$Creșteți la 4 bătăi.$q$, $q$Schimbați: bate el, voi repetați.$q$, $q$Încheiați cu bătăi tot mai rare, până la liniște.$q$]::text[], $q$A repetat corect cel puțin 2 ritmuri de 3 bătăi.$q$, $q$Ritm cu palme și genunchi (palmă, genunchi, palmă).$q$, $q$Tipar repetat ABAB: „palmă, genunchi, palmă, genunchi…”, apoi el continuă singur.$q$, null),
    ($q$s3-b23-z2-social$q$, $q$Ascultăm împreună la fereastră$q$, array[$q$Stați ureche spre fereastră 15–20 de secunde.$q$, $q$Spuneți: „Auzim împreună.”$q$, $q$Dacă vrea: arătați unul altuia ce ați auzit.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ascultăm și povestim ce s-a întâmplat afară$q$, array[$q$fereastra$q$]::text[], 8, array[$q$Stați la fereastră 1 minut și ascultați.$q$, $q$Întrebați: „Ce crezi că se întâmplă afară?” (o mașină trece, cineva taie lemne).$q$, $q$Inventați împreună o poveste scurtă cu sunetele auzite.$q$, $q$El o povestește cuiva din familie.$q$]::text[], $q$A legat un sunet de o întâmplare și a povestit-o cuiva.$q$, $q$„Cine face sunetul? Ce face el?”$q$, $q$Povestea continuă: „Și apoi ce s-a întâmplat?” El adaugă trei momente.$q$, null),
    ($q$s3-b23-z2-resurse$q$, $q$Jucăria sonoră în cutie$q$, array[$q$După joacă, puneți jucăria în cutie.$q$, $q$„La loc. Ajunge sunetul.”$q$, $q$Dacă vrea: alegeți cutia mare sau raftul.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cutia sunetelor, ordonată$q$, array[$q$3–4 jucării sonore; o cutie$q$]::text[], 5, array[$q$Pune el jucăriile în rând, de la cea mai tare la cea mai încetă.$q$, $q$Verificați: „Sună încet aceasta?”$q$, $q$Le pune în cutie în aceeași ordine.$q$, $q$Întrebați: „Care e cea mai bună pentru seară? De ce?”$q$]::text[], $q$A ordonat jucăriile după cât de tare sună și le-a strâns.$q$, $q$Două grupe: care sună când le scuturi și care sună când le apeși.$q$, $q$„Care jucărie nu face sunet deloc? Cum am putea-o face să sune?” (o lovim cu o lingură).$q$, null),
    ($q$s3-b23-z3-mental$q$, $q$Voce tare, voce încet$q$, array[$q$Spuneți același cuvânt tare, apoi încet: „Tare. Încet.”$q$, $q$Spuneți: „Liniște.” pe varianta încet.$q$, $q$Dacă vrea: el alege: „Spunem tare sau încet?”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Tare, încet, șoptit: același lucru, trei voci$q$, array[$q$o jucărie sau un ursuleț$q$]::text[], 8, array[$q$Spuneți aceeași propoziție în trei feluri: tare, încet, șoptit.$q$, $q$El repetă în cele trei feluri.$q$, $q$Voi spuneți un loc, el alege vocea: „La bibliotecă? În curte? Când doarme bebe?”$q$, $q$Întrebați: „De ce vorbim încet la bibliotecă?”$q$]::text[], $q$A folosit cele trei voci și a potrivit vocea cu cel puțin 2 locuri.$q$, $q$Vocea după emoție: vesel, supărat, obosit.$q$, $q$Ursulețul vorbește prea tare la culcare: „Cum îi explici?” El îi spune ursului regula și motivul.$q$, null),
    ($q$s3-b23-z3-fizic$q$, $q$Dans scurt, apoi oprire$q$, array[$q$Mișcați-vă 30–60 de secunde pe sunet.$q$, $q$Opriți muzica sau bătăile: „Gata. Liniște.”$q$, $q$Dacă vrea: încă 20 de secunde de dans, apoi iar oprire.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Dansul statuilor$q$, array[$q$o melodie (cântată sau de pe telefonul adultului)$q$]::text[], 8, array[$q$Când e muzică, dansați; când se oprește, statuie.$q$, $q$După câteva runde, statuile au o formă: „Statuie de copac!”$q$, $q$El alege forma statuii pentru voi.$q$, $q$Încheiați cu un dans foarte încet, apoi foarte repede.$q$]::text[], $q$A înghețat când s-a oprit muzica, de cel puțin 4 ori.$q$, $q$Statuie pe un picior (cu sprijin dacă e nevoie).$q$, $q$Regula pe dos: când e muzică, stai; când e liniște, dansezi.$q$, $q$Spațiu liber, fără colțuri ascuțite.$q$),
    ($q$s3-b23-z3-social$q$, $q$Cântec scurt cu familia$q$, array[$q$Cântați un refren cunoscut aproximativ un minut.$q$, $q$Nu forțați să cânte; poate doar asculta.$q$, $q$Dacă vrea: el alege cântecul dintre două pe care le știți.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cântecul cu mișcări care se adaugă$q$, array[$q$un cântec cunoscut al familiei$q$]::text[], 8, array[$q$Cântați împreună un refren cunoscut.$q$, $q$Adăugați o mișcare pentru un cuvânt (la „soare”, mâinile sus).$q$, $q$La a doua strofă, mai adăugați o mișcare; el ține minte amândouă.$q$, $q$El inventează a treia mișcare.$q$]::text[], $q$A ținut minte cel puțin 2 mișcări legate de cuvinte din cântec.$q$, $q$Cântecul cântat tot mai repede.$q$, $q$Cântec fără un cuvânt: în locul cuvântului facem doar mișcarea.$q$, null),
    ($q$s3-b23-z3-resurse$q$, $q$Oprim muzica — gata$q$, array[$q$Apăsați împreună oprirea: „Oprit.”$q$, $q$Puneți aparatul deoparte: „La loc.”$q$, $q$Dacă vrea: alegeți să lăsați liniștea încă 10 secunde.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Când oprim muzica?$q$, array[$q$telefonul sau difuzorul adultului$q$]::text[], 5, array[$q$Întrebați: „Cât ascultăm? Un cântec sau două?”$q$, $q$Oprește el la final (cu adult).$q$, $q$Pune aparatul la locul lui.$q$, $q$Întrebați: „Ce facem acum, după muzică?”$q$]::text[], $q$A respectat numărul de cântece stabilit și a oprit muzica.$q$, $q$Volumul: „Dăm puțin mai încet.”$q$, $q$„Cine din casă vrea liniște acum? Cum știm?” (bunica citește, bebe doarme).$q$, null),
    ($q$s3-b23-z4-mental$q$, $q$Pasăre sau mașină?$q$, array[$q$Ascultați afară sau din memorie: „Pasăre? Mașină?”$q$, $q$Arătați direcția sunetului dacă e real.$q$, $q$Dacă vrea: clasificați un al treilea sunet (voce, vânt).$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Sunetele de afară, în categorii$q$, array[$q$fereastra sau curtea; un carton cu 3 desene (pasăre, mașină, om)$q$]::text[], 10, array[$q$Ascultați 2 minute afară. La fiecare sunet, întrebați: „Cine face sunetul?”$q$, $q$Puneți câte o pietricică mare pe desenul potrivit (pasăre, mașină, om).$q$, $q$Întrebați: „Ce am auzit cel mai des?”$q$, $q$Sunetul care nu încape: „Vântul. Unde-l punem?”$q$]::text[], $q$A clasificat cel puțin 4 sunete în categorii.$q$, $q$Sunete de animale și sunete de mașini: „Care sunt mai multe azi?”$q$, $q$„Ce sunete am auzi într-un oraș mare? Dar în pădure?” Comparați.$q$, $q$Pietricele mai mari de 3,17 cm.$q$),
    ($q$s3-b23-z4-fizic$q$, $q$Sărituri pe bătăi$q$, array[$q$Bateți din palme; o săritură mică (cu sprijin dacă e nevoie).$q$, $q$2–4 repetări, apoi pauză.$q$, $q$Dacă vrea: el bate din palme, voi săriți o dată.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Sărim după numărul de bătăi$q$, array[$q$palmele$q$]::text[], 8, array[$q$Bateți o dată: o săritură. De două ori: două sărituri.$q$, $q$Creșteți până la 3.$q$, $q$El bate, voi săriți.$q$, $q$Încheiați cu o săritură foarte mică și una foarte mare.$q$]::text[], $q$A făcut atâtea sărituri câte bătăi a auzit, de cel puțin 3 ori.$q$, $q$Bătaie tare înseamnă săritură mare, bătaie încet înseamnă săritură mică.$q$, $q$Regula pe dos: o bătaie înseamnă două sărituri, două bătăi o săritură.$q$, $q$Pe covor sau iarbă, fără sărituri de pe înălțime.$q$),
    ($q$s3-b23-z4-social$q$, $q$Rândul la sunet$q$, array[$q$Voi faceți un sunet: „Acum eu.”$q$, $q$Apoi: „Acum tu” — așteptați.$q$, $q$Dacă vrea: încă un schimb, apoi gata.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ecou: eu spun, tu răspunzi$q$, array[$q$niciunul$q$]::text[], 6, array[$q$Spuneți un sunet sau un cuvânt; el repetă ca un ecou.$q$, $q$Creșteți la o propoziție scurtă.$q$, $q$Schimbați: spune el, voi faceți ecoul.$q$, $q$Faceți ecoul „greșit” o dată: „Ce n-am spus bine?”$q$]::text[], $q$A repetat cel puțin 3 propoziții scurte și a observat greșeala.$q$, $q$Ecoul în șoaptă.$q$, $q$Ecoul cu o schimbare: el spune „pisica mare”, voi spuneți „pisica mică”, el găsește diferența și o inventează pe următoarea.$q$, null),
    ($q$s3-b23-z4-resurse$q$, $q$Închidem ușa încet$q$, array[$q$Închideți fără trântit: „Încet. Liniște.”$q$, $q$Arătați diferența față de un zgomot tare (voi modelați blând).$q$, $q$Dacă vrea: el împinge ușa ultimele centimetri cu ajutor.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ușa care nu trântește$q$, array[$q$o ușă$q$]::text[], 5, array[$q$Închideți ușa tare (o singură dată, ca demonstrație) și apoi încet: „Ce diferență auzi?”$q$, $q$Închide el încet.$q$, $q$Întrebați: „De ce închidem încet?”$q$, $q$Când pleacă din cameră, închide singur încet.$q$]::text[], $q$A închis ușa încet și a spus de ce.$q$, $q$Sertarul la fel: tare și încet.$q$, $q$„Cum ieșim din cameră fără să-l trezim pe tata?” Planifică el ieșirea în liniște.$q$, $q$Degetele departe de balamale.$q$),
    ($q$s3-b23-z5-mental$q$, $q$Trei sunete din casă$q$, array[$q$Numeți trei surse: frigider, apă, voce (ce aveți).$q$, $q$Arătați fiecare pe scurt.$q$, $q$Dacă vrea: el alege care sunet îi place cel mai mult.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Perechile de sunete$q$, array[$q$6 recipiente identice, opace, cu capac lipit (două cu orez, două cu fasole, două goale) sau cilindrii sonori$q$]::text[], 10, array[$q$Scuturați două recipiente: „Sună la fel?”$q$, $q$El caută perechea fiecărui sunet.$q$, $q$Verificați deschizând doar recipientele voastre de control (sau întorcând cilindrii, dacă au semn dedesubt).$q$, $q$Întrebați: „Cum ai știut care e perechea?”$q$]::text[], $q$A găsit cel puțin 2 perechi de sunete.$q$, $q$Toate trei perechile.$q$, $q$Ordonați recipientele de la cel mai tare la cel mai încet sunet.$q$, $q$Capacele lipite bine; orezul și fasolea nu ajung la el.$q$),
    ($q$s3-b23-z5-fizic$q$, $q$Mers pe vârfuri — încercare$q$, array[$q$Arătați mers ușor pe câțiva pași.$q$, $q$Spuneți: „Pași liniștiți.”$q$, $q$Dacă vrea: comparați cu pași apăsați pe hol.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Pași de pisică, pași de urs$q$, array[$q$holul; podeaua de lemn sau pietrișul$q$]::text[], 8, array[$q$Mergeți ca pisica, fără zgomot, apoi ca ursul, apăsat.$q$, $q$Întrebați: „Cum faci pașii să nu se audă?”$q$, $q$Joc: voi stați cu ochii închiși, el se apropie ca pisica. Dacă îl auziți, o luați de la capăt.$q$, $q$Schimbați rolurile.$q$]::text[], $q$A ajuns la voi cel puțin o dată fără să fie auzit.$q$, $q$Pe două suprafețe: „Unde e mai ușor să mergi fără zgomot?”$q$, $q$Pisica duce ceva în mână (o pernă) fără zgomot.$q$, null),
    ($q$s3-b23-z5-social$q$, $q$Salut pe voce blândă$q$, array[$q$Spuneți: „Bună!” cu zâmbet, voce blândă.$q$, $q$Așteptați privirea sau răspunsul.$q$, $q$Dacă vrea: el alege voce tare sau blândă pentru salut.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Salutul cu vocea potrivită$q$, array[$q$niciunul$q$]::text[], 5, array[$q$Întrebați: „Cum îl saluți pe bebe care doarme? Dar pe tata, care e departe în curte?”$q$, $q$Salută el pe fiecare în felul potrivit.$q$, $q$Voi salutați greșit (strigați lângă cineva care doarme): „Am făcut bine?”$q$, $q$El vă corectează și arată cum.$q$]::text[], $q$A potrivit vocea cu situația de cel puțin 2 ori.$q$, $q$Salut fără voce (doar cu mâna) pentru cineva care vorbește la telefon.$q$, $q$Inventează el o situație nouă și vocea potrivită.$q$, null),
    ($q$s3-b23-z5-resurse$q$, $q$Telefonul pe silențios (exemplu)$q$, array[$q$Puneți telefonul pe silențios vizibil: „Acum liniște la telefon.”$q$, $q$Arătați că nu mai sună.$q$, $q$Dacă vrea: așezați telefonul pe locul lui de pe masă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ora liniștită a casei$q$, array[$q$telefonul adultului; o lumină$q$]::text[], 5, array[$q$Spuneți: „Acum e ora liniștită. Ce facem ca să fie liniște?”$q$, $q$Face el o listă: telefonul pe silențios, muzica oprită, ușa închisă încet.$q$, $q$Verifică el fiecare lucru.$q$, $q$Întrebați: „Ce se aude acum?”$q$]::text[], $q$A propus și a verificat cel puțin 2 lucruri pentru liniște.$q$, $q$Pune el telefonul pe silențios cu voi (arătat, fără să-l folosească).$q$, $q$„Ce sunet nu putem opri?” (frigiderul, vântul). Discutați.$q$, null),
    ($q$s3-b23-z6-mental$q$, $q$Vântul se aude?$q$, array[$q$Stați 15 secunde afară sau la fereastră.$q$, $q$„Vânt.” sau „Liniște.” — spuneți ce e adevărat.$q$, $q$Dacă vrea: clasificați: vânt / pasăre / liniște.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Detectivul de vânt$q$, array[$q$o panglică sau o pungă de plastic legată de un băț; fereastra sau curtea$q$]::text[], 10, array[$q$Ascultați 15 secunde: „Se aude vântul?”$q$, $q$Ieșiți cu panglica: „Cum știm că bate vântul, chiar dacă nu-l auzim?”$q$, $q$Comparați: panglica la adăpost de zid și în mijlocul curții.$q$, $q$Întrebați: „Unde bate vântul mai tare? De ce?”$q$]::text[], $q$A folosit panglica pentru a verifica vântul și a comparat două locuri.$q$, $q$Ce alte lucruri mișcă vântul (frunze, rufe)?$q$, $q$„Cum facem un lucru care cântă când bate vântul?” (clopoței, o sticlă). Încercați o idee.$q$, $q$Panglica scurtă, fără sfoară lungă la gât.$q$),
    ($q$s3-b23-z6-fizic$q$, $q$Pași pe pietriș sau iarbă$q$, array[$q$Pășiți pe două suprafețe care sună diferit.$q$, $q$„Auzi? Diferit.”$q$, $q$Dacă vrea: alegeți suprafața preferată și rămâneți 15 secunde.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Drumul sunetelor: pietriș, iarbă, frunze$q$, array[$q$curtea cu suprafețe diferite$q$]::text[], 10, array[$q$Mergeți pe pietriș, pe iarbă, pe frunze uscate: „Cum sună fiecare?”$q$, $q$El închide ochii; voi pășiți pe o suprafață: „Unde merg?”$q$, $q$Schimbați rolurile.$q$, $q$Întrebați: „Pe unde ai merge ca să nu te audă nimeni?”$q$]::text[], $q$A recunoscut cel puțin 2 suprafețe după sunet.$q$, $q$Cuvinte pentru sunete: „scârțâie”, „foșnește”, „scrâșnește”.$q$, $q$Un traseu pe care trebuie să-l facă fără zgomot (alegerea suprafețelor e a lui).$q$, null),
    ($q$s3-b23-z6-social$q$, $q$Comentăm sunetele lui$q$, array[$q$Joacă paralel: comentați sunetele pe care le face el.$q$, $q$Nu preluați jocul.$q$, $q$Dacă vrea: imitați o dată sunetul lui, apoi lăsați-l pe el.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Orchestra familiei$q$, array[$q$instrumente sau obiecte de casă (oală, lingură de lemn, cutie cu orez lipită)$q$]::text[], 10, array[$q$Fiecare alege un instrument.$q$, $q$El e dirijorul: arată cine cântă și când.$q$, $q$Încercați: tare, încet, toți împreună, câte unul.$q$, $q$La final, întrebați: „Cum a sunat cel mai frumos?”$q$]::text[], $q$A condus orchestra cu semne, cel puțin 3 schimbări.$q$, $q$Un instrument cântă doar când dirijorul arată spre el.$q$, $q$Povestea cântată: el spune o poveste scurtă, iar fiecare instrument e un personaj.$q$, $q$Instrumentele DIY bine închise.$q$),
    ($q$s3-b23-z6-resurse$q$, $q$Piatră liniștită față de jucăria sonoră$q$, array[$q$Comparați: piatra nu sună, jucăria sună.$q$, $q$Puneți ambele la loc după: „La loc.”$q$, $q$Dacă vrea: alegeți pe care o țineți 5 secunde.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ce sună și ce nu: sortăm$q$, array[$q$6 obiecte (piatră mare, clopoțel, cutie cu orez lipită, burete, lingură de metal, pernă); o cutie$q$]::text[], 6, array[$q$Scutură el fiecare obiect: „Sună?”$q$, $q$Sortează în două grămezi: „sună” și „nu sună”.$q$, $q$Întrebați: „Cum facem buretele să sune?” Încearcă el.$q$, $q$Strânge totul în cutie, la loc.$q$]::text[], $q$A sortat obiectele după sunet și a strâns cutia.$q$, $q$Sortare după două reguli: sună / nu sună și tare / moale.$q$, $q$Încercați cu o lingură: „Acum sună piatra? Dar perna?” Cum s-a schimbat regula?$q$, $q$Obiectele mai mari de 3,17 cm; cutia cu orez lipită bine.$q$),
    ($q$s3-b23-z7-mental$q$, $q$Carte liniștită$q$, array[$q$Răsfoiți încet, fără ecran.$q$, $q$Șoptiți cuvintele dacă citiți.$q$, $q$Dacă vrea: alegeți cartea favorită a săptămânii.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cartea cu sunete: o citim și o continuăm$q$, array[$q$„Mergem la vânătoare de urși” sau altă carte cu multe sunete$q$]::text[], 10, array[$q$Citiți cartea și faceți împreună sunetele („fâș-fâș”, „pleosc-pleosc”).$q$, $q$La pagina următoare, întrebați: „Ce sunet urmează?”$q$, $q$El face sunetele singur la o recitire.$q$, $q$Întrebați: „Ce sunet ți-a plăcut cel mai mult săptămâna asta?”$q$]::text[], $q$A ghicit cel puțin un sunet care urmează și a făcut sunetele singur.$q$, $q$Ordinea locurilor din carte (iarbă, râu, noroi…).$q$, $q$Inventează el un loc nou în carte și sunetul lui.$q$, null),
    ($q$s3-b23-z7-fizic$q$, $q$Plimbare liberă cu urechile deschise$q$, array[$q$El dictează ritmul; voi numiți sunete dacă apar.$q$, $q$Fără grabă, fără test.$q$, $q$Dacă vrea: reveniți la locul cel mai liniștit al săptămânii.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Plimbarea cu urechile ciulite$q$, array[$q$curtea$q$]::text[], 10, array[$q$El conduce; la fiecare oprire, ascultați 10 secunde.$q$, $q$Spune ce aude și de unde vine.$q$, $q$Revine la locul cel mai liniștit al săptămânii.$q$, $q$Întrebați: „De ce e liniște aici?”$q$]::text[], $q$A condus plimbarea și a numit sunetele la cel puțin 2 opriri.$q$, $q$Cel mai zgomotos loc: „De ce e zgomot aici?”$q$, $q$„Unde ne-am ascunde, ca să nu ne audă nimeni?” Alege el și explică.$q$, null),
    ($q$s3-b23-z7-social$q$, $q$Noapte bună șoptit$q$, array[$q$Șoaptă: „Noapte bună.”$q$, $q$Calm, fără grabă.$q$, $q$Dacă vrea: reamintiți sunetul preferat al săptămânii într-un cuvânt.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Noapte bună, în șoaptă, cu sunetul zilei$q$, array[$q$lumină mică$q$]::text[], 4, array[$q$Șoptiți: „Noapte bună.”$q$, $q$Întrebați în șoaptă: „Ce sunet ți-a plăcut azi?”$q$, $q$Îl imită el, foarte încet.$q$, $q$Îmbrățișare doar dacă vrea.$q$]::text[], $q$A ales și a imitat încet un sunet al zilei.$q$, $q$Un sunet pe care l-ați auzit amândoi.$q$, $q$„Ce sunete se aud noaptea?” Ascultați împreună 10 secunde.$q$, null),
    ($q$s3-b23-z7-resurse$q$, $q$Lumina stinsă încet$q$, array[$q$Stingeți cu adult: „Stins. Liniște.”$q$, $q$Respirați o dată împreună.$q$, $q$Dacă vrea: aprindeți iar puțin, apoi stingeți — ritual.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Stingem lumina după plan$q$, array[$q$întrerupătorul, cu adult$q$]::text[], 4, array[$q$Întrebați: „Ce facem înainte să stingem lumina?” (jucăriile la loc, apă, baie).$q$, $q$Face el lista în ordine și o urmează.$q$, $q$Stinge lumina cu voi.$q$, $q$Respirați împreună de trei ori.$q$]::text[], $q$A spus și a urmat un plan de 2–3 pași înainte de a stinge lumina.$q$, $q$Lumina de veghe: „O lăsăm aprinsă sau stinsă? De ce?”$q$, $q$Planul pentru mâine dimineață, spus de el în 3 pași.$q$, null),
    ($q$s4-b23-z1-mental$q$, $q$Numește degete și acțiuni$q$, array[$q$Arătați: „Mână. Deget.” Atingeți-i palma blând.$q$, $q$Spuneți: „Mână.” pe palma voastră.$q$, $q$Dacă vrea: numiți un deget: „Acesta e degetul mare.”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Ce face mâna? Verbe în acțiune$q$, array[$q$un coș cu 5 obiecte (cană, minge, burete, cutie cu capac, carte)$q$]::text[], 10, array[$q$Luați un obiect și întrebați: „Ce poate face mâna cu el?” (apucă, strânge, deschide, întoarce, aruncă).$q$, $q$El face acțiunea și o numește: „Strâng buretele.”$q$, $q$Voi spuneți o acțiune, el alege obiectul potrivit: „Ceva ce putem deschide.”$q$, $q$Întrebați: „Ce nu poate face mâna?” (zbura, mirosi).$q$]::text[], $q$A numit și a făcut cel puțin 4 acțiuni diferite ale mâinii.$q$, $q$Două acțiuni la rând: „Deschide cutia și pune mingea înăuntru.”$q$, $q$Trei acțiuni la rând, spuse o singură dată: „Ia cartea, întoarce o pagină, apoi pune-o pe raft.”$q$, null),
    ($q$s4-b23-z1-fizic$q$, $q$Deschide și strânge pumnul$q$, array[$q$Arătați: deschideți palma, apoi strângeți pumnul. De 3 ori.$q$, $q$Spuneți: „Deschis. Strâns.”$q$, $q$Dacă vrea: alegeți mâna dreaptă sau stângă pentru încă o rundă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Gimnastica degetelor$q$, array[$q$niciunul$q$]::text[], 8, array[$q$Faceți împreună: pumn, palmă deschisă, degetele „merg” pe masă.$q$, $q$Fiecare deget salută pe rând: „Bună, degetul mare!”$q$, $q$Încercați să ridicați un singur deget, apoi două.$q$, $q$El inventează o mișcare nouă pentru degete.$q$]::text[], $q$A făcut cel puțin 3 mișcări diferite cu degetele și a inventat una.$q$, $q$Cântecul cu degete („Degetul mare a mers la piață…”), cu mișcări.$q$, $q$Imitați o formă cu mâinile (un iepure, o casă, o pasăre), el ghicește, apoi el face una pentru voi.$q$, null),
    ($q$s4-b23-z1-social$q$, $q$Arată ce ai făcut cu mâna$q$, array[$q$După gest, arătați adultului: „Uite mâna mea!”$q$, $q$Aplauze blânde dacă vrea.$q$, $q$Dacă vrea: el arată din nou cuiva din casă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Arăt și explic ce am făcut$q$, array[$q$ceva făcut de el azi (un turn, un desen, un aluat)$q$]::text[], 6, array[$q$Duceți-vă împreună la cineva din familie: „Arată-i ce ai făcut.”$q$, $q$Întrebați: „Cum l-ai făcut?” El explică pașii.$q$, $q$Persoana pune o întrebare.$q$, $q$Încheiați: „Ce ți-a fost cel mai greu?”$q$]::text[], $q$A arătat ce a făcut și a explicat cel puțin 2 pași.$q$, $q$„Ce ai face altfel data viitoare?”$q$, $q$Îl învață pe celălalt să facă la fel, pas cu pas.$q$, null),
    ($q$s4-b23-z1-resurse$q$, $q$Capacul pe cutie — la loc$q$, array[$q$Puneți capacul împreună: „Capac. La loc.”$q$, $q$Fără frustrare — ajutați cât trebuie.$q$, $q$Dacă vrea: alegeți cutia mare sau cea mică.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Capace și cutii: potrivirea$q$, array[$q$4–5 cutii și borcane de plastic cu capace diferite$q$]::text[], 6, array[$q$Amestecați capacele lângă cutii: „Care capac e al cui?”$q$, $q$Încearcă el; voi întrebați „Se potrivește? Cum știi?”$q$, $q$Închide toate cutiile și le pune pe raft.$q$, $q$Întrebați: „Care a fost cel mai greu de închis? De ce?”$q$]::text[], $q$A potrivit cel puțin 3 capace cu cutiile lor.$q$, $q$Ordonați cutiile de la cea mai mică la cea mai mare.$q$, $q$Un capac care nu are cutie: „Ce lipsește? Unde o căutăm?”$q$, $q$Doar recipiente de plastic; fără sticlă.$q$),
    ($q$s4-b23-z2-mental$q$, $q$Ce face mâna? Apasă, trage$q$, array[$q$Arătați: „Apăs.” pe un buton sau întrerupător cu adult.$q$, $q$„Trag.” pe un sertar ușor.$q$, $q$Dacă vrea: spuneți: „Deschis.” când deschideți sertarul.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Apăs, trag, răsucesc: cum se deschide?$q$, array[$q$o placă sau o cutie cu 3–4 închideri (zăvor, buton, capac cu filet, fermoar) sau obiecte din casă$q$]::text[], 10, array[$q$Arătați 3 lucruri care se deschid diferit: sertar (tragi), borcan (răsucești), întrerupător (apeși).$q$, $q$Întrebați la fiecare: „Cum crezi că se deschide?”$q$, $q$Încearcă el și spune verbul: „Răsucesc.”$q$, $q$Întrebați: „Care a fost cel mai greu? De ce?”$q$]::text[], $q$A deschis cel puțin 3 lucruri și a numit corect cum se deschide fiecare.$q$, $q$Sortați obiectele din casă: „se deschid trăgând” și „se deschid răsucind”.$q$, $q$O ascunzătoare cu încuietoare (o cutie cu zăvor) cu o surpriză înăuntru: „Cum ajungi la ea?” Rezolvă el.$q$, $q$Fără mecanisme care prind degetele; încuietori mari.$q$),
    ($q$s4-b23-z2-fizic$q$, $q$Două unelte pe treabă reală$q$, array[$q$Alegeți două unelte sigure de bucătărie sau casă.$q$, $q$Amestecați scurt în bol gol sau ștergeți masa: treabă reală 1–2 minute.$q$, $q$Dacă vrea: alegeți unealta a doua după ce ați terminat cu prima.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Bucătarul: unelte potrivite pentru treabă$q$, array[$q$o lingură de lemn, un tel, o lingură mare, un burete; un bol cu făină și apă (sau orez)$q$]::text[], 10, array[$q$Arătați uneltele: „Cu ce amestecăm? Cu ce ștergem? Cu ce mutăm?”$q$, $q$Face el o treabă reală cu fiecare (amestecă, mută orezul, șterge masa).$q$, $q$Întrebați: „De ce nu ștergem cu telul?”$q$, $q$Alege el unealta pentru o treabă nouă.$q$]::text[], $q$A folosit cel puțin 3 unelte pentru treaba potrivită și a explicat o alegere.$q$, $q$Ordinea: întâi amestecăm, apoi turnăm, apoi ștergem.$q$, $q$Unealta lipsă: „Nu avem lingură. Cu ce mutăm orezul?” Găsește el o alternativă.$q$, $q$Fără cuțite; orezul și făina rămân în bol, sub supraveghere.$q$),
    ($q$s4-b23-z2-social$q$, $q$Ținem mâna pe rând$q$, array[$q$Oferiți mâna: „Vrei să ținem?” — nu forțați.$q$, $q$Dacă acceptă, țineți 10 secunde, apoi eliberați.$q$, $q$Dacă vrea: schimbați: acum el „oferă” mâna.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Mâna care ajută$q$, array[$q$o treabă pentru doi (cărat un coș, întins un cearșaf)$q$]::text[], 6, array[$q$Spuneți: „Asta nu pot face singur. Mă ajuți?”$q$, $q$Lucrați împreună: el ține de un capăt, voi de celălalt.$q$, $q$Întrebați: „Cum ne-am ajutat?”$q$, $q$Apoi el cere ajutor pentru o treabă a lui, cu propoziția lui.$q$]::text[], $q$A ajutat la o treabă în doi și a cerut ajutor cu o propoziție.$q$, $q$Coordonare: „La trei, ridicăm împreună.”$q$, $q$Întrebați: „Cine din casă are nevoie de ajutor acum? Cum îl ajutăm?” El caută și propune.$q$, null),
    ($q$s4-b23-z2-resurse$q$, $q$Uneltele la loc după$q$, array[$q$După treabă, luați uneltele.$q$, $q$Puneți-le la loc: „Lingura la loc. Cârpa la loc.”$q$, $q$Dacă vrea: el alege care unealtă merge prima.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Fiecare unealtă la locul ei$q$, array[$q$uneltele de ieri; un suport sau sertar cu loc fix$q$]::text[], 5, array[$q$Întrebați: „Unde stă telul? Dar lingura de lemn?”$q$, $q$Le spală el sub jet (cu voi), le șterge.$q$, $q$Le pune la loc.$q$, $q$Întrebați: „De ce le spălăm înainte să le punem la loc?”$q$]::text[], $q$A spălat, a șters și a pus la loc cel puțin 2 unelte.$q$, $q$Le așază după mărime.$q$, $q$„Dacă punem telul ud în sertar, ce se întâmplă?” Discutați.$q$, null),
    ($q$s4-b23-z3-mental$q$, $q$Degetul mare și celelalte$q$, array[$q$Arătați degetul mare: „Deget mare.”$q$, $q$Arătați celelalte: „Degete.”$q$, $q$Dacă vrea: spuneți: „Deget.” pe un deget arătat.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Degetul mare: ce facem fără el?$q$, array[$q$o bandă de hârtie sau un elastic moale; o lingură, un nasture mare, o cană$q$]::text[], 10, array[$q$Arătați: „Degetul mare stă altfel decât celelalte.”$q$, $q$Lipiți ușor degetul mare de palmă cu bandă de hârtie (sau îl ține el lipit).$q$, $q$Încearcă să ia lingura, cana, nasturele: „E mai ușor sau mai greu?”$q$, $q$Întrebați: „La ce ne ajută degetul mare?”$q$]::text[], $q$A încercat cel puțin 2 apucări fără degetul mare și a spus ce s-a schimbat.$q$, $q$Care lucru a fost cel mai greu de luat fără degetul mare?$q$, $q$„Ce animal n-are degete? Cum ia el mâncarea?” (pasărea cu ciocul, câinele cu gura).$q$, $q$Banda moale, scoasă imediat după; nasturele mai mare de 3,17 cm.$q$),
    ($q$s4-b23-z3-fizic$q$, $q$Degete în aluat sau nisip$q$, array[$q$Apăsați degetele în material: „Apăs. Urma degetului.”$q$, $q$Scoateți mâna: „Deschis.”$q$, $q$Dacă vrea: faceți două urme și comparați-le.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Aluatul nostru, din rețetă$q$, array[$q$1 cană de făină, ½ cană de sare fină, ½ cană de apă, 1 lingură de ulei; un bol; tavă$q$]::text[], 15, array[$q$Spuneți rețeta în 4 pași: „Făina, sarea, apa, frământăm.”$q$, $q$Toarnă el pe rând ingredientele (le măsurați voi).$q$, $q$Frământă el aluatul și spune ce simte: „lipicios”, „moale”.$q$, $q$Faceți urme: deget, palmă, o furculiță.$q$]::text[], $q$A pus ingredientele în ordine și a frământat aluatul.$q$, $q$Forme: un șarpe lung, o bilă, o turtă.$q$, $q$„Aluatul e prea lipicios. Ce adăugăm?” (făină). Lăsați-l să încerce soluția.$q$, $q$Aluatul nu se mănâncă (e foarte sărat); spălați mâinile după.$q$),
    ($q$s4-b23-z3-social$q$, $q$Arătăm urma adultului$q$, array[$q$Arătați urma degetului cuiva din casă.$q$, $q$„Uite ce am făcut!”$q$, $q$Dacă vrea: adultul face o urmă lângă a lui — pe rând.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Expoziția de urme$q$, array[$q$aluatul cu urme de ieri; o tavă$q$]::text[], 6, array[$q$Aranjează el urmele pe tavă.$q$, $q$Invită pe cineva la „expoziție”.$q$, $q$Persoana ghicește: „Ce urmă e asta?” El explică.$q$, $q$Adultul adaugă o urmă, el ghicește.$q$]::text[], $q$A explicat cel puțin 2 urme unui invitat.$q$, $q$Urmele în ordine: de la cea mai mică la cea mai mare.$q$, $q$Urma misterioasă: o urmă făcută cu un obiect ascuns. „Cu ce am făcut-o?” Încearcă el pe aluat până găsește.$q$, null),
    ($q$s4-b23-z3-resurse$q$, $q$Plastilina în cutie$q$, array[$q$Strângeți materialul: „Ajunge.”$q$, $q$În cutie: „La loc.”$q$, $q$Dacă vrea: alegeți capacul închis sau doar cutia deschisă pe scurt.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Aluatul pus la păstrare$q$, array[$q$aluat; o cutie cu capac; o pungă$q$]::text[], 5, array[$q$Întrebați: „Ce se întâmplă cu aluatul dacă îl lăsăm afară?”$q$, $q$Lasă el o bucățică pe tavă și pune restul în cutie.$q$, $q$A doua zi, comparați: „Care e moale? Care e tare?”$q$, $q$Pune el cutia la loc.$q$]::text[], $q$A pus aluatul în cutie și a comparat a doua zi cele două bucăți.$q$, $q$Spune el regula: „Aluatul stă în cutie, ca să rămână moale.”$q$, $q$„Cum am putea face o bucată tare intenționat?” (o lăsăm la uscat, o coacem cu adult).$q$, null),
    ($q$s4-b23-z4-mental$q$, $q$Câte degete țin obiectul?$q$, array[$q$Țineți obiectul cu toată mâna, apoi cu două degete (modelați).$q$, $q$„Multe degete. Puține degete.”$q$, $q$Dacă vrea: el alege cum ține — toată mâna sau două degete.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cu toată mâna, cu două degete, cu clește$q$, array[$q$6 obiecte (minge, cub de lemn, pompon mare, lingură, frunză mare, castană mare de 4 cm+); un clește de bucătărie din lemn$q$]::text[], 10, array[$q$Încearcă el să ia fiecare obiect cu toată mâna, apoi cu două degete.$q$, $q$Întrebați: „Cu ce merge mai bine? De ce?”$q$, $q$Încearcă cu clește.$q$, $q$Sortează el obiectele: „cu toată mâna” și „cu două degete”.$q$]::text[], $q$A încercat cel puțin 2 feluri de apucare și a sortat obiectele.$q$, $q$Mută 4 obiecte cu clește, dintr-un bol în altul.$q$, $q$Un obiect alunecos (un cub de gheață mare într-un bol): „Cum îl iei?” Încearcă mai multe metode.$q$, $q$Obiecte mai mari de 3,17 cm; castanele doar cu adult.$q$),
    ($q$s4-b23-z4-fizic$q$, $q$Scoatem și punem obiecte mici$q$, array[$q$Scoateți obiectele din bol cu mâna, unul câte unul.$q$, $q$Puneți-le înapoi: „Înăuntru.”$q$, $q$Dacă vrea: alegeți să sortați după culoare în două boluri.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Transfer cu clește și lingură$q$, array[$q$două boluri; 8 pomponi mari sau bile de lemn de 4 cm+; un clește de lemn; o lingură$q$]::text[], 10, array[$q$Mută el obiectele dintr-un bol în altul cu lingura.$q$, $q$Apoi cu clește.$q$, $q$Întrebați: „Cu care e mai repede? Cu care e mai ușor?”$q$, $q$Sortează la final după culoare, în două boluri.$q$]::text[], $q$A mutat obiectele cu ambele unelte și le-a comparat.$q$, $q$Sortare după culoare în timpul transferului.$q$, $q$Două criterii deodată: „Pomponii roșii cu clește în bolul albastru; bilele de lemn cu lingura în cel verde.”$q$, $q$Toate piesele mai mari de 3,17 cm; număr cunoscut de piese, numărate la final.$q$),
