    ($q$s4-b23-z4-resurse$q$, $q$Bolul pe raft după joacă$q$, array[$q$După joacă, duceți bolul la raft.$q$, $q$„Bolul la loc.”$q$, $q$Dacă vrea: ștergeți marginea bolului cu o cârpă înainte.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Bolurile pe raft, în turn$q$, array[$q$3–4 boluri de plastic de mărimi diferite$q$]::text[], 5, array[$q$Întrebați: „Cum punem bolurile ca să ocupe puțin loc?”$q$, $q$Încearcă el să le pună unul în altul.$q$, $q$Dacă nu merg, întrebați: „Care trebuie să fie dedesubt?”$q$, $q$Le duce pe raft.$q$]::text[], $q$A pus bolurile unul în altul, de la mare la mic, și le-a dus pe raft.$q$, $q$Bolurile și capacele lor potrivite.$q$, $q$Un bol lipsă din serie: „Ce mărime lipsește?”$q$, null),
    ($q$s4-b23-z5-mental$q$, $q$Mâna stângă, mâna dreaptă$q$, array[$q$Arătați: „Mâna asta. Mâna cealaltă.” (fără a forța etichete stânga/dreapta).$q$, $q$Puneți un obiect pe o mână: „Pe mâna aceasta.”$q$, $q$Dacă vrea: spuneți: „Mână.” pe ambele pe rând.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Mâna asta și mâna cealaltă$q$, array[$q$un ceas sau o brățară (pentru o mână); o mănușă$q$]::text[], 8, array[$q$Puneți brățara pe o mână: „Mâna cu brățara e mâna asta.”$q$, $q$Jucați: „Ridică mâna cu brățara. Acum cealaltă.”$q$, $q$Puneți mănușa pe mâna fără brățară.$q$, $q$Întrebați: „Care mână are brățara și care mănușa?”$q$]::text[], $q$A arătat corect mâna cerută, după semn, de cel puțin 3 ori.$q$, $q$Introducem cuvintele „dreapta” și „stânga”, doar dacă e interesat; fără verificare.$q$, $q$Oglinda: stați față în față. „Ridic mâna cu brățara. Tu care ridici?” (pentru un copil de 2 ani e greu; e un joc, nu un test).$q$, null),
    ($q$s4-b23-z5-fizic$q$, $q$Ștergem masa cu cârpa$q$, array[$q$Ștergeți împreună o zonă mică de pe masă.$q$, $q$Mișcări scurte cu mâna: „Ștergem.”$q$, $q$Dacă vrea: alegeți zona — colțul lui sau mijlocul.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Spălăm masa ca un profesionist$q$, array[$q$o cârpă umedă; un pulverizator mic cu apă; un prosop uscat$q$]::text[], 10, array[$q$Spuneți ordinea: „Pulverizăm, ștergem, uscăm.”$q$, $q$Face el fiecare pas.$q$, $q$Întrebați: „E curat? Cum verificăm?” (cu palma, cu ochii de aproape).$q$, $q$Șterge el și scaunele.$q$]::text[], $q$A făcut cei 3 pași în ordine și a verificat rezultatul.$q$, $q$Ștergere în linii, de la un capăt la altul, ca să nu sară vreo bucată.$q$, $q$O pată lipicioasă (puțină miere): „Nu se ia cu apă. Ce încercăm?” (apă caldă, săpun).$q$, $q$Doar apă în pulverizator, fără detergenți.$q$),
