    ($q$s4-b23-z5-resurse$q$, $q$Cârpa la uscat — la loc$q$, array[$q$După șters, puneți cârpa la uscat pe locul ei.$q$, $q$„Cârpa la loc.”$q$, $q$Dacă vrea: alegeți cârligul sau marginea chiuvetei.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cârpa la uscat: unde se usucă mai repede?$q$, array[$q$două cârpe ude$q$]::text[], 6, array[$q$Întrebați: „Unde punem cârpa să se usuce?”$q$, $q$El pune o cârpă la soare și una la umbră (sau una întinsă și una mototolită).$q$, $q$Verificați după o oră: „Care e mai uscată?”$q$, $q$Întrebați: „De ce?”$q$]::text[], $q$A pus cârpele în două locuri și a comparat după o oră.$q$, $q$Întinsă și mototolită, ambele la soare.$q$, $q$„Cum ar trebui să întindem rufele, ca să se usuce repede?” Spune el regula.$q$, null),
    ($q$s4-b23-z6-mental$q$, $q$Ce încape în mână?$q$, array[$q$Arătați: „Încape în mână.” / „Prea mare pentru o mână.”$q$, $q$Lăsați-l să încerce ambele.$q$, $q$Dacă vrea: sortați încă un obiect în cele două categorii.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Încape în mână? Mare, mic, cât de mare$q$, array[$q$6 obiecte de mărimi diferite; o cutie mică; un coș$q$]::text[], 10, array[$q$Încearcă el să țină fiecare obiect într-o mână: „Încape?”$q$, $q$Sortează: „încape” și „nu încape”.$q$, $q$Ordonează obiectele de la cel mai mic la cel mai mare.$q$, $q$Întrebați: „Dar în mâna mea? Încap mai multe?” Verificați.$q$]::text[], $q$A sortat și a ordonat cel puțin 5 obiecte după mărime.$q$, $q$Prezice înainte de încercare: „Crezi că încape?”$q$, $q$„Ce încape în cutia mică? Dar în coș?” Sortare cu trei categorii: mână, cutie, coș.$q$, $q$Obiecte mai mari de 3,17 cm.$q$),
