    ($q$s4-b23-z6-social$q$, $q$Rândul la deschis cutia$q$, array[$q$Voi deschideți: „Acum eu.”$q$, $q$El încearcă: „Acum tu.”$q$, $q$Dacă vrea: încă un schimb, apoi închideți împreună.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Atelierul cu rândul și cu sfatul$q$, array[$q$placa cu încuietori sau cutia cu capace$q$]::text[], 8, array[$q$Lucrați pe rând: „Acum eu, acum tu.”$q$, $q$Când unul se blochează, celălalt poate da un sfat, dar nu pune mâna.$q$, $q$Voi vă blocați intenționat: „Ce să fac?” El vă dă un sfat în cuvinte.$q$, $q$Mulțumiți pentru sfat.$q$]::text[], $q$A așteptat rândul și a dat cel puțin un sfat în cuvinte, fără să ia obiectul.$q$, $q$Sfatul spus în 2 pași: „Întâi tragi, apoi răsucești.”$q$, $q$Voi vă blocați din nou, dar acum el trebuie să explice fără să arate cu mâna.$q$, null),
    ($q$s4-b23-z6-resurse$q$, $q$Cutia pe raft — gata$q$, array[$q$După joacă, cutia pe raft.$q$, $q$„La loc. Gata.”$q$, $q$Dacă vrea: verificați dacă mai e o unealtă de pus — alegeți 1 din 2.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Cutia de unelte a mâinilor$q$, array[$q$o cutie; uneltele din săptămână (clește, lingură, burete, șurubul mare)$q$]::text[], 5, array[$q$Strânge el uneltele săptămânii în cutie.$q$, $q$Întrebați la fiecare: „La ce ne-a folosit?”$q$, $q$Hotărăște ordinea în cutie.$q$, $q$Pune cutia pe raft.$q$]::text[], $q$A strâns uneltele și a spus la ce a folosit cel puțin 2.$q$, $q$Etichetă desenată de voi pe cutie, el alege desenul.$q$, $q$„Ce unealtă am mai vrea săptămâna viitoare? Pentru ce?”$q$, null),
    ($q$s4-b23-z7-mental$q$, $q$Ce ne-a plăcut cu degetele?$q$, array[$q$Arătați 2–3 opțiuni din săptămână (capac, aluat, șters).$q$, $q$Întrebați: „Care ți-a plăcut?”$q$, $q$Dacă vrea: spuneți o frază: „Ne-a plăcut că…”$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Săptămâna mâinilor, povestită$q$, array[$q$aluatul, uneltele, placa de încuietori$q$]::text[], 10, array[$q$Întindeți obiectele săptămânii: „Ce am făcut cu mâinile săptămâna asta?”$q$, $q$El alege un obiect și povestește.$q$, $q$Întrebați: „Ce a fost cel mai greu? Cum ai reușit?”$q$, $q$Încheiați: „Ce ți-a plăcut cel mai mult? De ce?”$q$]::text[], $q$A povestit cel puțin 2 activități și ce a fost greu la una dintre ele.$q$, $q$Activitățile în ordine.$q$, $q$„Ce mai poate face mâna, la care nu ne-am gândit?” (să mângâie, să scrie, să cânte la pian).$q$, null),
    ($q$s4-b23-z7-fizic$q$, $q$Joaca favorită cu mâinile$q$, array[$q$Reluați pe scurt jocul cu mâinile care i-a plăcut.$q$, $q$El dictează ritmul; voi urmăriți.$q$, $q$Dacă vrea: alegeți între două favorita ale săptămânii.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Jocul favorit cu mâinile, ceva mai greu$q$, array[$q$materialul ales de el$q$]::text[], 10, array[$q$Alege el jocul favorit al săptămânii.$q$, $q$Îl reia, cât vrea.$q$, $q$Întrebați: „Cum îl facem puțin mai greu?”$q$, $q$Încearcă varianta propusă de el.$q$]::text[], $q$A reluat jocul favorit și a propus o variantă mai grea.$q$, $q$Varianta propusă de voi, dacă el nu are una.$q$, $q$Îl învață pe altcineva din familie jocul.$q$, null),
    ($q$s4-b23-z7-social$q$, $q$Ritual: mână pe mână, noapte bună$q$, array[$q$Atingeți palmele scurt dacă vrea: „Mână pe mână.”$q$, $q$„Noapte bună.” Calm.$q$, $q$Dacă vrea: spuneți: „Deschis” pe palmă, apoi odihnă.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Mână pe mână: noapte bună$q$, array[$q$niciunul$q$]::text[], 4, array[$q$Atingeți palmele, dacă vrea: „Mână pe mână.”$q$, $q$Întrebați: „Ce au făcut azi mâinile tale?”$q$, $q$Spune el un lucru.$q$, $q$„Noapte bună, mâini.”$q$]::text[], $q$A spus un lucru făcut azi cu mâinile.$q$, $q$Mulțumire pentru mâinile cuiva („Mulțumesc, mama, că m-ai ajutat”).$q$, $q$„Ce vor face mâinile mâine?” Plan scurt.$q$, null),
    ($q$s4-b23-z7-resurse$q$, $q$Totul la loc — mâini libere$q$, array[$q$Strângeți un obiect sau două: „La loc.”$q$, $q$Arătați mâinile goale: „Mâini libere. Gata.”$q$, $q$Dacă vrea: păstrați un obiect favorit la vedere.$q$]::text[], $q$Vârsta 2–3: scurt, fără forțare; el poate refuza. Extensia e opțională.$q$, $q$Mâini libere, cameră strânsă$q$, array[$q$lucrurile rămase$q$]::text[], 5, array[$q$Întrebați: „Ce mai e de strâns?”$q$, $q$Strânge el, după un plan spus de el.$q$, $q$Arată mâinile goale: „Mâini libere!”$q$, $q$Alege un obiect favorit care rămâne la vedere.$q$]::text[], $q$A strâns după planul lui și a ales obiectul favorit.$q$, $q$Împarte sarcinile cu voi.$q$, $q$Estimează: „Câte lucruri sunt de strâns?” Numărați după.$q$, null);

  if (select count(*) from gifted_plan) <> 112 then
    raise exception 'Gifted S1–S4: planul are % rânduri, așteptam 112', (select count(*) from gifted_plan);
  end if;

  if to_regclass('public.backup_20261116_gifted_s1s4') is null then
    create table public.backup_20261116_gifted_s1s4 as
    select *
    from public.activities
    where banda = '2-3'
      and saptamana between 1 and 4;

  end if;

  alter table public.backup_20261116_gifted_s1s4 enable row level security;
  revoke all on public.backup_20261116_gifted_s1s4 from public, anon, authenticated;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'backup_20261116_gifted_s1s4'
      and column_name = 'nota'
  ) then
    raise exception 'Gifted S1–S4: backup-ul nu are coloana nota';
  end if;

  if (select count(*) from public.backup_20261116_gifted_s1s4) <> 112 then
    raise exception 'Gifted S1–S4: backup-ul are % rânduri, așteptam 112',
      (select count(*) from public.backup_20261116_gifted_s1s4);
  end if;

  if exists (
    select 1
    from public.backup_20261116_gifted_s1s4 as snap_row
    full join gifted_plan as plan_row on plan_row.id = snap_row.id
    where plan_row.id is null
      or snap_row.id is null
      or snap_row.banda is distinct from '2-3'
      or snap_row.saptamana not between 1 and 4
  ) then
    raise exception 'Gifted S1–S4: backup-ul nu conține exact cele 112 id-uri din banda 2–3, S1–S4';
  end if;

  for plan in select * from gifted_plan order by id loop
    select titlu, pasi, nota into snap_titlu, snap_pasi, snap_nota
    from public.backup_20261116_gifted_s1s4
    where id = plan.id
      and banda = '2-3';

    if not found then
      raise exception 'Gifted S1–S4: id lipsă din backup: %', plan.id;
    end if;

    if snap_titlu is distinct from plan.old_titlu
       or snap_pasi is distinct from plan.old_pasi
       or snap_nota is distinct from plan.old_nota then
      raise exception 'Gifted S1–S4: backup-ul pentru % nu are titlul, pașii sau nota exportate pe 16.11.2026', plan.id;
    end if;

    select titlu, pasi, materiale, durata_min, gata_cand, pas_in_plus, provocare, siguranta, nota
      into cur_titlu, cur_pasi, cur_materiale, cur_durata, cur_gata, cur_plus, cur_provocare, cur_siguranta, cur_nota
    from public.activities
    where id = plan.id
      and banda = '2-3';

    if not found then
      raise exception 'Gifted S1–S4: id lipsă din banda 2–3: %', plan.id;
    end if;

    if cur_titlu = plan.titlu
       and cur_pasi = plan.pasi
       and cur_materiale = plan.materiale
       and cur_durata = plan.durata_min
       and cur_gata = plan.gata_cand
       and cur_plus is not distinct from plan.pas_in_plus
       and cur_provocare is not distinct from plan.provocare
       and cur_siguranta is not distinct from plan.siguranta
       and cur_nota is null then
      skipped_count := skipped_count + 1;
      continue;
    end if;

    if cur_titlu = plan.titlu
       and cur_pasi = plan.pasi
       and cur_materiale = plan.materiale
       and cur_durata = plan.durata_min
       and cur_gata = plan.gata_cand
       and cur_plus is not distinct from plan.pas_in_plus
       and cur_provocare is not distinct from plan.provocare
       and cur_siguranta is not distinct from plan.siguranta then
      if cur_nota is distinct from plan.old_nota then
        raise exception 'Gifted S1–S4: % nu are nota veche din backup', plan.id;
      end if;
      update public.activities
      set nota = null
      where id = plan.id
        and banda = '2-3'
        and nota is not distinct from plan.old_nota;
      get diagnostics touched = row_count;
      if touched <> 1 then
        raise exception 'Gifted S1–S4: % nota nu s-a golit (rânduri %)', plan.id, touched;
      end if;
      updated_count := updated_count + 1;
      continue;
    end if;

    if cur_titlu is distinct from plan.old_titlu
       or cur_pasi is distinct from plan.old_pasi
       or cur_nota is distinct from plan.old_nota then
      raise exception 'Gifted S1–S4: % nu are titlul, pașii sau nota veche din backup', plan.id;
    end if;

    update public.activities
    set
      titlu = plan.titlu,
      materiale = plan.materiale,
      durata_min = plan.durata_min,
      pasi = plan.pasi,
      gata_cand = plan.gata_cand,
      pas_in_plus = plan.pas_in_plus,
      provocare = plan.provocare,
      siguranta = plan.siguranta,
      nota = null
    where id = plan.id
      and banda = '2-3'
      and titlu = plan.old_titlu
      and pasi = plan.old_pasi
      and nota is not distinct from plan.old_nota;

    get diagnostics touched = row_count;
    if touched <> 1 then
      raise exception 'Gifted S1–S4: % nu s-a actualizat (rânduri %)', plan.id, touched;
    end if;
    updated_count := updated_count + 1;
  end loop;

  if updated_count + skipped_count <> 112 then
    raise exception 'Gifted S1–S4: închise % actualizate și % deja noi, așteptam 112',
      updated_count, skipped_count;
  end if;

